alter table public.bedtime_stories drop constraint if exists bedtime_stories_kind_check;
alter table public.bedtime_stories add constraint bedtime_stories_kind_check
  check (kind in ('value', 'hadith', 'prophet'));

do $$
declare
  st jsonb;
  data jsonb := $json$[{"id":"s01-honest-rabbit","sort":10,"title":"الأرنب الصادق","emoji":"🐰","value_code":"sidq","value_name":"الصدق","kind":"value","minutes":4,"source":"","min_grade":1,"max_grade":12,"pages":[{"bg":"garden","scene":["🐰","🌷","🏡"],"text":"في قريةٍ صغيرةٍ خضراء، كان يعيش أرنبٌ أبيضُ لطيفٌ اسمه رَنّوش. كان رنّوش يحبُّ القفزَ بين الأزهار، ويحبُّ جدّتَه الأرنبةَ العجوزَ كثيرًا. وكانت جدّتُه تزرعُ في شرفةِ بيتها أصيصًا جميلًا فيه زهرةٌ حمراءُ، تسقيها كلَّ صباحٍ وتبتسمُ لها، وتقول: هذه الزهرةُ هديةٌ من جدِّك، أحبُّها كثيرًا."},{"bg":"garden","scene":["🐰","⚽","🪴"],"text":"وفي يومٍ مشمس، كان رنّوش يلعبُ بالكرةِ قربَ الشرفة. ركلَ الكرةَ بقوّةٍ فارتفعتْ عاليًا، ثم نزلتْ على الأصيص، فسقطَ على الأرض، وانكسرَ قليلًا، وتناثرَ التراب. توقّفَ رنّوش مكانَه، ونظرَ إلى الزهرةِ الحمراءِ المائلة، وشعرَ بقلبِه يدقُّ بسرعة."},{"bg":"garden","scene":["🐰","🤔","🌳"],"text":"لم يكنْ أحدٌ قد رآه. فكّرَ رنّوش: هل أختبئُ خلفَ الشجرة؟ هل أقولُ إنَّ الريحَ هي التي أسقطتْه؟ لكنَّه تذكّرَ كلامَ أمِّه حين قالت له: الصدقُ يا صغيري نورٌ في القلب، ومَن يقولُ الحقَّ يرتاحُ ويطمئنّ. أخذَ رنّوش نفسًا عميقًا، ثم نفسًا آخر، وقرّرَ أنْ يكونَ صادقًا."},{"bg":"home","scene":["🐰","👵","🪴"],"text":"مشى رنّوش ببطءٍ إلى جدّتِه، وقال بصوتٍ هادئ: جدّتي، أنا آسف. كنتُ ألعبُ بالكرة، فأسقطتُ الأصيصَ من غيرِ قصد، وانكسرَ قليلًا. نظرتْ إليه الجدّةُ طويلًا، ثم ابتسمتْ ابتسامةً دافئة، وضمّتْه إلى صدرِها، وقالت: شكرًا لأنّك قلتَ الحقيقة يا رنّوش. الأصيصُ يمكنُ إصلاحُه، أمّا الصدقُ فهو أغلى من كلِّ الأصص."},{"bg":"garden","scene":["🐰","👵","🌷"],"text":"ثم قالت الجدّة: تعالَ نُصلحْه معًا. أحضرا أصيصًا جديدًا، ووضعا فيه ترابًا ناعمًا، وزرعا الزهرةَ الحمراءَ بعناية، وسقياها بالماء. وبعد أيّامٍ قليلة، صارت الزهرةُ أجملَ من قبل، وظهرتْ بجانبِها زهرةٌ صغيرةٌ جديدة. قالت الجدّة وهي تضحك: انظرْ يا رنّوش، حتّى الزهرةُ فرحتْ بصدقِك."},{"bg":"night","scene":["🐰","🌙","✨"],"text":"في تلك الليلة، نامَ رنّوش في سريرِه الدافئ وهو مرتاحُ البال. لم يكنْ في قلبِه خوفٌ ولا همّ، لأنَّه قال الحقيقة. نظرَ إلى القمرِ من النافذة، وهمسَ: الصدقُ يجعلُ القلبَ خفيفًا مثلَ الريشة. ثم أغمضَ عينيه، ونامَ نومًا هادئًا جميلًا. تصبحُ على خير يا صغيري، وكنْ دائمًا صادقًا مثلَ رنّوش."}],"question":{"q":"ماذا فعلَ رنّوش بعدَ أنْ انكسرَ الأصيص؟","options":["اختبأَ خلفَ الشجرة","قالَ الحقيقةَ لجدّتِه","قالَ إنَّ الريحَ أسقطتْه"],"answer":1},"activity":"قبلَ أنْ تنام، تذكّرْ موقفًا قلتَ فيه الحقيقة، واحكِه لأمِّك أو لأبيك بصوتٍ هادئ."},
{"id":"s02-blue-bag","sort":20,"title":"الحقيبةُ الزرقاء","emoji":"🎒","value_code":"amana","value_name":"الأمانة","kind":"value","minutes":4,"source":"","min_grade":1,"max_grade":12,"pages":[{"bg":"garden","scene":["👦","🌳","🪑"],"text":"كان سالمٌ ولدًا في الثامنةِ من عمرِه، يحبُّ الذهابَ مع أبيه إلى الحديقةِ القريبةِ من البيت كلَّ مساء. هناك يركضُ على العشبِ الأخضر، ويُطعمُ العصافيرَ فُتاتَ الخبز، ويجلسُ مع أبيه على المقعدِ الخشبيِّ يتحدّثان ويضحكان حتّى تغيبَ الشمس."},{"bg":"garden","scene":["👦","🎒","🪑"],"text":"وفي مساءٍ هادئ، رأى سالمٌ حقيبةً زرقاءَ صغيرةً تحتَ أحدِ المقاعد. نظرَ حولَه فلم يجدْ أحدًا. فتحَ الحقيبةَ بلطفٍ ليعرفَ صاحبَها، فوجدَ فيها نقودًا، ومفاتيحَ، وصورةً لطفلةٍ صغيرةٍ تبتسم، وبطاقةً مكتوبًا عليها اسمٌ ورقمُ هاتف."},{"bg":"garden","scene":["👦","💭","🍦"],"text":"خطرَ في بالِ سالمٍ خاطرٌ صغير: بهذه النقودِ أستطيعُ أنْ أشتريَ مثلّجاتٍ كثيرة. لكنّه هزَّ رأسَه وقال في نفسِه: هذه ليستْ لي، إنّها أمانة. وتذكّرَ أنَّ صاحبَ الحقيبةِ قد يكونُ حزينًا الآن ويبحثُ عنها في كلِّ مكان. حملَ الحقيبةَ بحرصٍ، وركضَ إلى أبيه."},{"bg":"garden","scene":["👨","👦","📱"],"text":"قال سالم: يا أبي، وجدتُ هذه الحقيبة، وفيها رقمُ هاتفِ صاحبِها. ابتسمَ الأبُ وربّتَ على كتفِه وقال: أحسنتَ يا بنيّ، هيّا نتّصلُ به. اتّصلَ الأبُ بالرقم، فأجابتْه امرأةٌ بصوتٍ قلق، وقالت: نعم، إنّها حقيبتي، أضعتُها وأنا ألعبُ مع ابنتي، وقد بحثتُ عنها طويلًا."},{"bg":"garden","scene":["👩","👧","🎒"],"text":"بعدَ دقائقَ جاءتْ المرأةُ ومعها ابنتُها الصغيرة، الطفلةُ نفسُها التي في الصورة. سلّمَها سالمٌ الحقيبةَ كما هي، لم ينقصْ منها شيء. فرحتِ المرأةُ فرحًا كبيرًا، وقالت: جزاك اللهُ خيرًا يا سالم، أنتَ ولدٌ أمين. وأهدتْه الطفلةُ الصغيرةُ وردةً بيضاءَ وهي تبتسم."},{"bg":"night","scene":["👦","🌼","🌙"],"text":"في طريقِ العودة، قال الأبُ: يا سالم، الأمانةُ أنْ نحفظَ أشياءَ الناسِ ونردَّها إليهم، والأمينُ يحبُّه اللهُ ويحبُّه الناس. وفي الليل، وضعَ سالمٌ الوردةَ البيضاءَ في كوبِ ماءٍ بجانبِ سريرِه، ونظرَ إليها وهو يشعرُ بسعادةٍ لا تُشترى بالنقود. ثم أغمضَ عينيه ونامَ مطمئنًّا. تصبحُ على خير يا صغيري الأمين."}],"question":{"q":"ماذا فعلَ سالمٌ بالحقيبةِ الزرقاء؟","options":["اشترى بها مثلّجات","تركَها تحتَ المقعد","أعادَها إلى صاحبتِها"],"answer":2},"activity":"اختَرْ مع أهلِك مكانًا ثابتًا لأغراضِك وأغراضِ إخوتِك، وتذكّرْ أنْ تُعيدَ كلَّ شيءٍ تستعيرُه إلى صاحبِه."},
{"id":"s03-warm-milk","sort":30,"title":"كوبُ الحليبِ الدافئ","emoji":"🥛","value_code":"birr","value_name":"بِرُّ الوالدين","kind":"value","minutes":3,"source":"","min_grade":1,"max_grade":12,"pages":[{"bg":"home","scene":["👧","👩","🏠"],"text":"كانت نور طفلةً لطيفةً تحبُّ أمَّها كثيرًا. كلَّ يومٍ تستيقظُ الأمُّ مبكّرًا، تُعدُّ الفطور، وترتّبُ البيت، وتذهبُ إلى عملِها، ثم تعودُ لتطبخَ الغداءَ وتساعدَ نورَ في دروسِها. وكانت نورُ تلاحظُ أنَّ أمَّها تفعلُ أشياءَ كثيرةً من أجلِها ومن أجلِ إخوتِها."},{"bg":"dusk","scene":["👩","🛋️","😴"],"text":"وفي مساءِ أحدِ الأيّام، جلستِ الأمُّ على الأريكةِ وقد بدا عليها التعب. وضعتْ يدَها على رأسِها وأغمضتْ عينيها قليلًا. نظرتْ نورُ إليها وفكّرتْ: أمّي تتعبُ كثيرًا من أجلنا، ماذا أستطيعُ أنْ أفعلَ لأُسعِدَها؟"},{"bg":"home","scene":["👧","🥛","🍯"],"text":"ذهبتْ نورُ إلى المطبخِ بهدوء، وطلبتْ من أبيها أنْ يساعدَها. سخّنا معًا كوبًا من الحليب، ووضعتْ فيه نورُ ملعقةً صغيرةً من العسل. ثم أخذتْ وسادةً ناعمة، وبطّانيّةً خفيفة، ومشتْ على أطرافِ أصابعِها حتّى لا تُزعجَ أمَّها."},{"bg":"home","scene":["👧","👩","💝"],"text":"وضعتْ نورُ الوسادةَ خلفَ ظهرِ أمِّها، وغطّتْ قدميها بالبطّانيّة، وقدّمتْ لها كوبَ الحليبِ الدافئ، وقالت بصوتٍ رقيق: تفضّلي يا أمّي، أنتِ تتعبين من أجلنا، وأنا أحبُّك كثيرًا. فتحتِ الأمُّ عينيها، وامتلأ وجهُها بالفرح، وقالت: بارك اللهُ فيكِ يا نور، هذا أجملُ كوبِ حليبٍ شربتُه في حياتي."},{"bg":"home","scene":["👧","🧸","✨"],"text":"ولم تتوقّفْ نورُ عند ذلك، بل رتّبتْ ألعابَها في صندوقِها، ووضعتْ حذاءَها في مكانِه، وساعدتْ أخاها الصغيرَ في جمعِ أقلامِه. قال الأبُ مبتسمًا: يا نور، إنَّ برَّ الوالدين من أحبِّ الأعمالِ إلى الله، والبرُّ يكونُ بالكلمةِ الطيّبة، وبالمساعدة، وبالابتسامة."},{"bg":"night","scene":["👧","👩","🌙"],"text":"وفي الليل، جلستِ الأمُّ بجانبِ سريرِ نور، ومسحتْ على شعرِها، ودعتْ لها: اللهمَّ احفظْ نورَ واجعلْها سعيدةً دائمًا. ابتسمتْ نورُ وقبّلتْ يدَ أمِّها، وقالت: وأنا أدعو لكِ يا أمّي كلَّ ليلة: ربِّ ارحمْهما كما ربّياني صغيرًا. ثم نامتْ نورُ وهي تشعرُ بالدفءِ والحبّ. تصبحُ على خير يا صغيري البارّ."}],"question":{"q":"ماذا قدّمتْ نورُ لأمِّها المتعبة؟","options":["كوبَ حليبٍ دافئٍ ووسادة","لعبةً جديدة","قطعةَ حلوى كبيرة"],"answer":0},"activity":"قبلَ النوم، قلْ لأمِّك أو أبيك كلمةً جميلة، وادعُ لهما: ربِّ ارحمْهما كما ربّياني صغيرًا."},
{"id":"s04-kitten-rain","sort":40,"title":"القطّةُ الصغيرةُ والمطر","emoji":"🐱","value_code":"rahma","value_name":"الرحمة","kind":"value","minutes":3,"source":"","min_grade":1,"max_grade":12,"pages":[{"bg":"dusk","scene":["👦","🌧️","🏠"],"text":"في مساءٍ من أيّامِ الشتاء، كان المطرُ ينزلُ رذاذًا خفيفًا على المدينة، وكان يوسفُ يجلسُ قربَ النافذةِ يسمعُ صوتَ القطراتِ وهي تنقرُ الزجاجَ بلطف: تِك، تِك، تِك. كان الجوُّ باردًا، وكان يوسفُ ملفوفًا ببطّانيّتِه الصوفيّةِ الدافئة."},{"bg":"dusk","scene":["🐱","🌧️","🌳"],"text":"وفجأةً سمعَ صوتًا ضعيفًا: مِياو، مِياو. نظرَ من النافذة، فرأى قطّةً صغيرةً رماديّةً تجلسُ تحتَ الشجرةِ، وقد ابتلَّ فروُها وهي ترتجفُ من البرد. شعرَ يوسفُ بقلبِه يرقُّ لها، وقال: مسكينةٌ هذه القطّة، لا بدَّ أنّها جائعةٌ وبردانة."},{"bg":"home","scene":["👦","👨","☂️"],"text":"أسرعَ يوسفُ إلى أبيه وقال: يا أبي، هناك قطّةٌ صغيرةٌ تحتَ المطر، هل نساعدُها؟ ابتسمَ الأبُ وقال: طبعًا يا يوسف، فالرحمةُ بالحيوانِ من الأخلاقِ التي يحبُّها الله. أخذَ الأبُ المظلّة، وأحضرَ يوسفُ صندوقًا صغيرًا ومنشفةً قديمةً ناعمة."},{"bg":"home","scene":["👦","🐱","📦"],"text":"حملَ الأبُ القطّةَ برفق، ووضعَها يوسفُ في الصندوق، وجفّفَ فروَها بالمنشفةِ بهدوءٍ حتّى توقّفتْ عن الارتجاف. ثم وضعَ لها صحنًا صغيرًا فيه ماءٌ نظيف، وقليلًا من الطعام. أكلتِ القطّةُ حتّى شبعتْ، ثم نظرتْ إلى يوسفَ بعينيها الخضراوين، وأغمضتهما ببطءٍ كأنّها تقولُ له: شكرًا."},{"bg":"home","scene":["🐱","🧶","🔥"],"text":"وضعَ يوسفُ الصندوقَ في زاويةٍ دافئةٍ من البيت، فتكوّرتِ القطّةُ على نفسِها، وبدأتْ تُصدرُ صوتًا ناعمًا: خُرْ، خُرْ، خُرْ. ضحكَ يوسفُ وقال: إنّها سعيدة! قالتِ الأمّ: نعم، وفي الصباحِ نبحثُ عن صاحبِها، فإنْ لم نجدْه فسنعتني بها حتّى تكبرَ وتقوى."},{"bg":"night","scene":["👦","🐱","🌙"],"text":"توقّفَ المطرُ، وخرجَ القمرُ من بين الغيوم، ولمعتِ النجوم. استلقى يوسفُ في سريرِه، وقال لأمِّه: يا أمّي، شعرتُ بفرحٍ كبيرٍ حين ساعدتُ القطّة. قالتِ الأمّ: هذه هي الرحمة يا بنيّ، مَن يرحمُ الصغيرَ والضعيفَ يرحمُه الله. أغمضَ يوسفُ عينيه، ونامَ وهو يبتسم، وفي الزاويةِ نامتِ القطّةُ الصغيرةُ في دفءٍ وأمان."}],"question":{"q":"كيف ساعدَ يوسفُ القطّةَ الصغيرة؟","options":["تركَها تحتَ المطر","جفّفَها وأطعمَها ووضعَها في مكانٍ دافئ","أغلقَ النافذة ونام"],"answer":1},"activity":"اسألْ أهلَك: كيف نستطيعُ أنْ نرحمَ الحيوانات؟ مثلًا: نضعُ ماءً للعصافيرِ على الشرفةِ في الأيّامِ الحارّة."},
{"id":"s05-squirrel-bridge","sort":50,"title":"جسرُ السنجاب","emoji":"🐿️","value_code":"help","value_name":"مساعدةُ الآخرين","kind":"value","minutes":3,"source":"","min_grade":1,"max_grade":12,"pages":[{"bg":"forest","scene":["🐿️","🌲","🌰"],"text":"في غابةٍ هادئةٍ تغنّي فيها العصافير، كان يعيشُ سنجابٌ نشيطٌ اسمه بُندُق. كان بندقُ يحبُّ جمعَ الجوزِ والبلّوط، ويقفزُ من شجرةٍ إلى شجرةٍ بخفّة. وفي وسطِ الغابةِ كان يجري جدولٌ صغير، ماؤه صافٍ ولامع، يسمعُ الجميعُ خريرَه الجميل."},{"bg":"forest","scene":["🐢","🦔","🌊"],"text":"وفي صباحِ أحدِ الأيّام، اشتدَّ ماءُ الجدولِ بعد ليلةٍ ممطرة، فصارَ أعرضَ من قبل. وعلى ضفّتِه وقفتِ السلحفاةُ العجوز، والقنفذُ الصغير، والأرنبةُ الأمُّ مع صغارِها، ينظرون إلى الضفّةِ الأخرى حيثُ الأشجارُ المثمرة، ولا يستطيعون العبور."},{"bg":"forest","scene":["🐿️","💡","🪵"],"text":"رآهم بندقُ من فوقِ الشجرة، فنزلَ وسألهم بلطف: ما بكم يا أصدقائي؟ قالتِ السلحفاة: نريدُ أنْ نعبرَ إلى الضفّةِ الأخرى، لكنَّ الماءَ صارَ واسعًا. فكّرَ بندقُ قليلًا، ثم لمعتْ في رأسِه فكرة، وقال: لا تقلقوا، سنصنعُ معًا جسرًا صغيرًا."},{"bg":"forest","scene":["🐿️","🦫","🪵"],"text":"ذهبَ بندقُ إلى صديقِه القُندُس، وطلبَ منه المساعدة، فجاءَ القندسُ مسرورًا. دحرجا معًا جذعًا طويلًا كان ملقًى على الأرض، ووضعاه فوقَ الجدولِ من ضفّةٍ إلى ضفّة، وثبّتاه بالحجارةِ والأغصان. وجمعتِ الأرنبةُ أوراقًا عريضةً وفرشتْها فوقَ الجذعِ حتّى لا يكونَ زلِقًا."},{"bg":"forest","scene":["🐢","🐇","🦔"],"text":"مشى الجميعُ على الجسرِ واحدًا بعد الآخر، ببطءٍ وهدوء. أمسكَ بندقُ بيدِ القنفذِ الصغير، وسارَ بجانبِ السلحفاةِ العجوزِ خطوةً خطوة، حتّى وصلوا جميعًا إلى الضفّةِ الأخرى سالمين. قالتِ السلحفاةُ بصوتٍ دافئ: شكرًا يا بندق، لقد جعلتَ يومَنا جميلًا."},{"bg":"night","scene":["🐿️","🌰","🌙"],"text":"وفي المساء، رجعَ بندقُ إلى بيتِه في جذعِ الشجرةِ العالية، فوجدَ عند بابِه كومةً من الجوزِ والتوت، هديّةً من أصدقائِه. ابتسمَ وقال: عندما نساعدُ غيرَنا، تمتلئُ قلوبُنا بالفرح. ثم تكوّرَ في عشِّه الناعم، ولفَّ ذيلَه الكبيرَ حولَه مثلَ بطّانيّة، ونامَ على صوتِ الجدولِ الهادئ. تصبحُ على خير يا صغيري المساعد."}],"question":{"q":"كيف ساعدَ بندقُ أصدقاءَه على عبورِ الجدول؟","options":["صنعَ معهم جسرًا من جذعِ شجرة","حملَهم على ظهرِه","قالَ لهم: ارجعوا إلى بيوتكم"],"answer":0},"activity":"فكّرْ في شيءٍ صغيرٍ تساعدُ به أحدًا غدًا: أنْ تحملَ شيئًا مع أمِّك، أو تُعيرَ قلمَك لصديقِك."},
{"id":"s06-broken-kite","sort":60,"title":"الطائرةُ الورقيّة","emoji":"🪁","value_code":"afw","value_name":"العفوُ والتسامح","kind":"value","minutes":4,"source":"","min_grade":1,"max_grade":12,"pages":[{"bg":"garden","scene":["👦","🪁","☁️"],"text":"كان عمّارٌ يحبُّ طائرتَه الورقيّةَ الملوّنةَ كثيرًا. صنعَها مع جدِّه من الورقِ الأزرقِ والأصفر، وربطا بها ذيلًا طويلًا من الشرائطِ الحمراء. وفي كلِّ عصرٍ كان يخرجُ إلى الساحةِ الواسعة، فيطيّرُها عاليًا في السماء، وتتراقصُ مع النسيمِ كأنّها عصفورٌ سعيد."},{"bg":"garden","scene":["👦","👦🏽","🪁"],"text":"وفي يومٍ جاءَ صديقُه خالد، وقال: يا عمّار، هل تسمحُ لي أنْ أطيّرَها قليلًا؟ أعطاه عمّارُ الخيط، وقال: انتبهْ، إنّها غالية عليّ. ركضَ خالدٌ فرحًا، لكنَّ قدمَه تعثّرتْ بحجر، فسقطَ، وسقطتِ الطائرةُ على الأرضِ، وانكسرَ عودٌ من أعوادِها، وتمزّقَ طرفُ الورق."},{"bg":"garden","scene":["👦","😢","🪁"],"text":"شعرَ عمّارُ بالحزن، وكادَ أنْ يصرخَ في وجهِ خالد. لكنّه رأى خالدًا ينهضُ ببطء، ووجهُه حزينٌ جدًّا، وعيناه تلمعان، وقال بصوتٍ خافت: أنا آسفٌ يا عمّار، لم أقصدْ ذلك أبدًا. سكتَ عمّارُ قليلًا، وأخذَ نفسًا عميقًا، وتذكّرَ كلامَ جدِّه: العفوُ يجعلُ القلوبَ أقربَ وأجمل."},{"bg":"garden","scene":["👦","🤝","👦🏽"],"text":"اقتربَ عمّارُ من صديقِه، ووضعَ يدَه على كتفِه، وقال: لا بأسَ يا خالد، أنا أسامحُك، المهمُّ أنّك لم تتأذَّ. ابتسمَ خالدٌ ابتسامةً كبيرة، وكأنَّ حِملًا ثقيلًا نزلَ عن قلبِه، وقال: شكرًا يا عمّار، هيّا نصلحُها معًا."},{"bg":"home","scene":["👴","👦","🪁"],"text":"ذهبَ الصديقان إلى الجدّ، فأحضرَ لهما عودًا جديدًا، وقليلًا من الغراء، وورقةً ملوّنة. ألصقا الورقَ بعناية، وربطا العودَ الجديدَ بالخيط. وأضافَ خالدٌ شريطًا أخضرَ جميلًا إلى الذيل. قالَ الجدُّ وهو يبتسم: انظرا، صارتِ الطائرةُ أجملَ من قبل، مثلَ صداقتِكما بعد التسامح."},{"bg":"night","scene":["🪁","⭐","🌙"],"text":"في اليومِ التالي، طيّرَ الصديقان الطائرةَ معًا، وارتفعتْ عاليًا حتّى بدتْ صغيرةً بين الغيوم. وفي الليل، علّقَ عمّارُ طائرتَه على جدارِ غرفتِه، ونظرَ إليها قبلَ النوم، وقال في نفسِه: لو غضبتُ لخسرتُ صديقي، لكنّي سامحتُ فربحتُه. ثم نامَ مرتاحَ القلب. تصبحُ على خير يا صغيري المتسامح."}],"question":{"q":"ماذا قالَ عمّارُ لخالدٍ بعد أنْ انكسرتِ الطائرة؟","options":["لن ألعبَ معك أبدًا","لا بأس، أنا أسامحُك","اذهبْ واشترِ لي طائرةً جديدة"],"answer":1},"activity":"إذا زعّلك أحدٌ اليوم، فكّرْ: هل أستطيعُ أنْ أسامحَه؟ وإنْ أخطأتَ أنت، فقلْ: أنا آسف."},
{"id":"s07-grandpa-seat","sort":70,"title":"مقعدُ الجدّ","emoji":"👴","value_code":"respect","value_name":"احترامُ الكبير","kind":"value","minutes":3,"source":"","min_grade":1,"max_grade":12,"pages":[{"bg":"home","scene":["👧","🚌","🏙️"],"text":"كانت مريمُ تحبُّ ركوبَ الحافلةِ مع أمِّها يومَ الجمعةِ لزيارةِ بيتِ جدّتِها. كانت تجلسُ قربَ النافذة، وتنظرُ إلى الأشجارِ والبيوتِ وهي تمرُّ واحدةً بعد الأخرى، وتعدُّ السيّاراتِ الحمراءَ في الطريق: واحدة، اثنتان، ثلاث."},{"bg":"home","scene":["👴","🦯","🚌"],"text":"وفي إحدى المحطّات، صعدَ إلى الحافلةِ رجلٌ كبيرٌ في السنّ، شعرُه أبيضُ مثلَ القطن، ويمشي ببطءٍ مستندًا إلى عصاه. نظرَ حولَه فلم يجدْ مقعدًا فارغًا، فوقفَ ممسكًا بالعمودِ، والحافلةُ تهتزُّ به قليلًا."},{"bg":"home","scene":["👧","💭","👴"],"text":"رأتْ مريمُ الرجلَ الكبير، وتذكّرتْ ما قالتْه لها معلّمتُها في المدرسة: الكبيرُ له علينا حقُّ الاحترامِ والتقدير، نقدّمُه في الجلوس، ونخفضُ صوتَنا عند الحديثِ معه، ونساعدُه إذا احتاجَ. نظرتْ إلى أمِّها، فهزّتِ الأمُّ رأسَها مبتسمةً كأنّها فهمتْ ما تفكّرُ فيه."},{"bg":"home","scene":["👧","💺","👴"],"text":"قامتْ مريمُ من مقعدِها، واقتربتْ من الرجلِ، وقالت بأدب: تفضّلْ يا عمّي، اجلسْ مكاني. ابتسمَ الرجلُ ابتسامةً واسعة، وجلسَ ببطء، وقال: شكرًا يا ابنتي، بارك اللهُ فيكِ وفي والديكِ اللذين ربّياكِ هذه التربيةَ الجميلة."},{"bg":"home","scene":["👴","🍬","👧"],"text":"وفي الطريق، حكى الرجلُ الكبيرُ لمريمَ عن أيّامِ صغرِه، وكيف كان يزرعُ النخيلَ مع أبيه، ويسقيه من الفلج. استمعتْ مريمُ إليه باهتمام، ولم تقاطعْه. وعندما وصلَ إلى محطّتِه، أعطاها قطعةَ حلوى صغيرة، وقال: أنتِ جعلتِ رحلتي جميلة."},{"bg":"night","scene":["👧","👵","🌙"],"text":"حكتْ مريمُ القصّةَ لجدّتِها، فضمّتْها الجدّةُ وقالت: يا مريم، ليس منّا مَن لا يرحمُ صغيرَنا ويوقّرُ كبيرَنا، هكذا علّمَنا نبيُّنا صلّى اللهُ عليه وسلّم. وفي تلك الليلة، نامتْ مريمُ في بيتِ جدّتِها، وجدّتُها تمسحُ على رأسِها وتدعو لها. تصبحُ على خير يا صغيري المؤدَّب."}],"question":{"q":"ماذا فعلتْ مريمُ عندما رأتِ الرجلَ الكبيرَ واقفًا؟","options":["أعطتْه مقعدَها","نظرتْ من النافذة","ضحكتْ بصوتٍ عالٍ"],"answer":0},"activity":"في المرّةِ القادمةِ التي ترى فيها جدَّك أو جدّتَك، قبّلْ رأسَه أو يدَه، واسألْه عن قصّةٍ من أيّامِ صغرِه."},
{"id":"s08-kind-word","sort":80,"title":"الكلمةُ الطيّبة","emoji":"😊","value_code":"manners","value_name":"حُسنُ التعامل","kind":"value","minutes":3,"source":"","min_grade":1,"max_grade":12,"pages":[{"bg":"home","scene":["👦","🏪","🍞"],"text":"كان حمدٌ يذهبُ كلَّ صباحٍ مع أبيه إلى المخبزِ الصغيرِ في آخرِ الشارع. وكان صاحبُ المخبزِ رجلًا طيّبًا اسمه العمُّ سعيد، يخبزُ الخبزَ الساخنَ منذُ الفجر، فتفوحُ رائحتُه الجميلةُ في الحيِّ كلِّه."},{"bg":"home","scene":["👨‍🍳","😓","🍞"],"text":"وفي أحدِ الأيّام، كان المخبزُ مزدحمًا جدًّا، والعمُّ سعيدٌ يعملُ بسرعة، ووجهُه متعب. ورأى حمدٌ رجلًا يرفعُ صوتَه ويقول: أسرعْ، لقد تأخّرت! وطفلًا آخرَ يأخذُ الخبزَ دون أنْ يقولَ شيئًا. لاحظَ حمدٌ أنَّ العمَّ سعيدًا صارَ حزينًا قليلًا."},{"bg":"home","scene":["👦","💭","😊"],"text":"فكّرَ حمدٌ: ماذا أستطيعُ أنْ أفعلَ لأُفرحَ العمَّ سعيدًا؟ وتذكّرَ أنَّ أباه قال له مرّة: الكلمةُ الطيّبةُ صدقة، والابتسامةُ في وجهِ أخيك صدقة. فقرّرَ أنْ ينتظرَ دورَه بهدوء، وأنْ يستعدَّ بأجملِ كلامٍ يعرفُه."},{"bg":"home","scene":["👦","👨‍🍳","🥖"],"text":"عندما جاءَ دورُه، ابتسمَ حمدٌ وقال: صباحُ الخيرِ يا عمّي سعيد، من فضلك أريدُ خمسَ خبزات. وعندما أعطاه الخبز، قال: شكرًا جزيلًا، خبزُك أطيبُ خبزٍ في العالم، أعانك اللهُ على تعبِك. توقّفَ العمُّ سعيدٌ لحظة، ثم ضحكَ ضحكةً كبيرة، وزالَ التعبُ عن وجهِه."},{"bg":"home","scene":["👨‍🍳","🥐","👦"],"text":"قال العمُّ سعيد: يا حمد، كلماتُك أراحتْ قلبي أكثرَ من فنجانِ قهوة. وأعطاه كعكةً صغيرةً بالسمسم هديّة. ومنذ ذلك اليوم، صارَ الناسُ في المخبزِ يسمعون حمدًا فيقلّدونه: من فضلك، وشكرًا، وجزاك اللهُ خيرًا، حتّى صارَ المخبزُ أهدأَ وأجمل."},{"bg":"night","scene":["👦","📖","🌙"],"text":"وفي الليل، سألَ حمدٌ أباه: هل الكلماتُ الصغيرةُ تغيّرُ الناسَ فعلًا؟ قال الأب: نعم يا بنيّ، حسنُ التعاملِ مثلُ المطرِ الخفيف، يسقي القلوبَ فتُزهر. ابتسمَ حمدٌ وسحبَ الغطاءَ حتّى كتفيه، وقال: غدًا سأقولُ كلمةً طيّبةً لكلِّ مَن أقابلُه. ثم نامَ هادئًا. تصبحُ على خير يا صاحبَ الكلمةِ الطيّبة."}],"question":{"q":"ما الكلماتُ التي قالها حمدٌ للعمِّ سعيد؟","options":["أسرعْ لقد تأخّرت","من فضلك، وشكرًا جزيلًا","لم يقلْ شيئًا"],"answer":1},"activity":"العبْ مع أهلِك لعبةَ الكلماتِ الطيّبة: كلُّ واحدٍ يقولُ كلمةً جميلةً للآخر قبلَ النوم."},
{"id":"s09-thank-you","sort":90,"title":"نِعَمٌ في غرفتي","emoji":"🤲","value_code":"shukr","value_name":"الشكر","kind":"value","minutes":3,"source":"","min_grade":1,"max_grade":12,"pages":[{"bg":"night","scene":["👧","🛏️","🌙"],"text":"في ليلةٍ هادئة، استلقتْ ليلى في سريرِها، لكنّها لم تستطعِ النومَ بسرعة. كانت منزعجةً قليلًا، لأنّها أرادتْ لعبةً جديدةً رأتْها في المتجر، ولم تشترِها لها أمُّها. قالت ليلى بصوتٍ حزين: يا أمّي، ليس عندي أشياءُ جميلة."},{"bg":"night","scene":["👩","👧","🕯️"],"text":"جلستِ الأمُّ بجانبِها، وأضاءتْ مصباحًا صغيرًا بضوءٍ أصفرَ هادئ، وقالت: هيّا نلعبْ لعبةً قبلَ النوم اسمُها: نِعَمٌ في غرفتي. سنبحثُ عن النِّعمِ التي أعطانا اللهُ إيّاها، وكلّما وجدْنا نعمةً قلنا: الحمدُ لله."},{"bg":"night","scene":["👀","👂","🖐️"],"text":"قالتِ الأمّ: انظري إلى عينيكِ، بهما ترينَ القمرَ والزهورَ ووجهَ أبيكِ. قالت ليلى: الحمدُ لله. وأذناكِ، تسمعين بهما صوتَ المطرِ والعصافير. الحمدُ لله. ويداكِ، ترسمين بهما وتعانقين بهما مَن تحبّين. ابتسمتْ ليلى وقالت: الحمدُ لله، هذه نِعَمٌ كثيرة!"},{"bg":"home","scene":["🛏️","💧","🍎"],"text":"ثم نظرتا حولَهما في الغرفة. قالت ليلى: هذا سريرٌ دافئ، الحمدُ لله. وهذا كوبُ ماءٍ نظيفٍ بجانبي، الحمدُ لله. وهذه تفّاحةٌ للصباح، الحمدُ لله. وهذا البيتُ الذي يحمينا من البردِ والمطر، الحمدُ لله. وصارتْ ليلى تجدُ النِّعمَ في كلِّ زاوية."},{"bg":"home","scene":["👨","👩","👧"],"text":"ثم قالت ليلى بفرح: وأنتِ يا أمّي، وأبي، وأخي الصغير، أنتم أجملُ نعمة! الحمدُ لله. ضمّتْها الأمُّ وقالت: أحسنتِ يا ليلى، ومن شكرِ النعمةِ أنْ نقولَ شكرًا لمن يساعدُنا، وأنْ نستعملَ النِّعمَ في الخير. قالت ليلى: شكرًا يا أمّي على كلِّ ما تفعلينه من أجلي."},{"bg":"night","scene":["👧","🤲","✨"],"text":"نسيتْ ليلى اللعبةَ الجديدةَ تمامًا، وشعرتْ أنَّ قلبَها ممتلئٌ بالرضا. رفعتْ يديها الصغيرتين وقالت: الحمدُ للهِ على كلِّ شيء. أطفأتِ الأمُّ المصباح، وبقيَ ضوءُ القمرِ الفضّيُّ يلمعُ على الوسادة. أغمضتْ ليلى عينيها، ونامتْ وهي تبتسم. تصبحُ على خير يا صغيري الشاكر، ولا تنسَ أنْ تقولَ: الحمدُ لله."}],"question":{"q":"ما اسمُ اللعبةِ التي لعبتْها ليلى مع أمِّها؟","options":["نِعَمٌ في غرفتي","الغميضة","سباقُ السيّارات"],"answer":0},"activity":"عُدَّ على أصابعِك خمسَ نِعَمٍ أعطاك اللهُ إيّاها، وقلْ بعد كلِّ واحدة: الحمدُ لله."},
{"id":"s10-suads-seed","sort":100,"title":"بذرةُ سُعاد","emoji":"🌱","value_code":"sabr","value_name":"الصبر","kind":"value","minutes":3,"source":"","min_grade":1,"max_grade":12,"pages":[{"bg":"garden","scene":["👧","🌰","🪴"],"text":"في أوّلِ أيّامِ الربيع، أعطى الجدُّ حفيدتَه سعادَ بذرةً صغيرةً بنّيّة، وقال: يا سعاد، هذه بذرةُ زهرةِ دوّارِ الشمس. ازرعيها، واسقيها، واعتني بها، وسترينَ شيئًا جميلًا. فرحتْ سعادُ كثيرًا، وزرعتِ البذرةَ في أصيصٍ صغيرٍ قربَ النافذة."},{"bg":"home","scene":["👧","🪴","❓"],"text":"في الصباحِ التالي، ركضتْ سعادُ إلى الأصيص، فلم تجدْ شيئًا، التربةُ كما هي. وفي اليومِ الثالثِ لم تجدْ شيئًا أيضًا. قالت بحزن: يا جدّي، البذرةُ لا تكبر! ضحكَ الجدُّ ضحكةً خفيفة وقال: الأشياءُ الجميلةُ تحتاجُ إلى صبرٍ يا صغيرتي. البذرةُ تعملُ الآن تحتَ التراب، حتّى لو لم نرَها."},{"bg":"home","scene":["👧","💧","☀️"],"text":"صبرتْ سعاد. كانت تسقي البذرةَ كلَّ يومٍ قليلًا من الماء، وتضعُ الأصيصَ في ضوءِ الشمس، وتقولُ لها بلطف: كبري ببطءٍ يا بذرتي، أنا أنتظرُك. وكانت كلّما شعرتْ بالملل، تذكّرتْ كلامَ جدِّها: الصبرُ مفتاحُ الفرج."},{"bg":"garden","scene":["🌱","👧","😮"],"text":"وفي صباحِ اليومِ العاشر، صاحتْ سعادُ بفرح: جدّي، جدّي، تعالَ بسرعة! كانت هناك ورقتان خضراوان صغيرتان تخرجان من التراب، مثلَ يدين صغيرتين تلوّحان للشمس. قال الجدُّ: أرأيتِ؟ صبرُكِ بدأَ يُثمر."},{"bg":"garden","scene":["🌻","👧","🐝"],"text":"ومرّتِ الأسابيع، والنبتةُ تطولُ يومًا بعد يوم، حتّى صارتْ أطولَ من سعادَ نفسِها! وفي صباحٍ مشرق، تفتّحتْ زهرةٌ صفراءُ كبيرةٌ تشبهُ الشمس، وجاءتِ النحلاتُ تزورُها وتطنُّ حولَها بسعادة. وقفتْ سعادُ تحتَها مبتسمةً وقالت: كانت تستحقُّ الانتظار."},{"bg":"night","scene":["🌻","🌙","👧"],"text":"في تلك الليلة، قالت سعادُ لجدِّها: تعلّمتُ أنَّ الصبرَ جميل، وأنَّ اللهَ يحبُّ الصابرين. قال الجدّ: نعم يا سعاد، وكلُّ شيءٍ نتعلّمُه يحتاجُ إلى صبر، مثلَ القراءة، والحفظ، وتعلّمِ الكلماتِ الجديدة. نامتْ سعادُ وهي تحلمُ بحديقةٍ مليئةٍ بزهورِ دوّارِ الشمس. تصبحُ على خير يا صغيري الصبور."}],"question":{"q":"ماذا تعلّمتْ سعادُ من بذرتِها؟","options":["أنَّ البذورَ لا تنمو أبدًا","أنَّ الأشياءَ الجميلةَ تحتاجُ إلى صبر","أنْ تتركَ الأصيصَ بلا ماء"],"answer":1},"activity":"ازرعْ مع أهلِك بذرةَ عدسٍ أو فولٍ في قطنٍ مبلول، وراقبْها كلَّ يومٍ بصبر."},
{"id":"h01-thirsty-dog","sort":110,"title":"الرجلُ والكلبُ العطشان","emoji":"🐕","value_code":"rahma","value_name":"الرحمة","kind":"hadith","minutes":3,"source":"صحيح البخاري (2363) وصحيح مسلم (2244)، عن أبي هريرة رضي الله عنه","min_grade":1,"max_grade":12,"pages":[{"bg":"desert","scene":["🌙","✨","📖"],"text":"يا صغيري، هذه الليلةَ سأحكي لك قصّةً حقيقيّة، حكاها نبيُّنا محمّدٌ صلّى اللهُ عليه وسلّم لأصحابِه، ورواها الصحابيُّ الجليلُ أبو هريرة رضي الله عنه. وهي قصّةٌ عن الرحمة، وعن أنَّ اللهَ يحبُّ مَن يرحمُ حتّى الحيوانات."},{"bg":"desert","scene":["🚶","☀️","🏜️"],"text":"أخبرَنا النبيُّ صلّى اللهُ عليه وسلّم أنَّ رجلًا كان يمشي في طريق، فاشتدَّ عليه العطش. تخيّلْ يا صغيري طريقًا طويلًا والشمسُ حارّة، والرجلُ يبحثُ عن ماء. فوجدَ بئرًا، فنزلَ فيها فشربَ حتّى ارتوى، ثم خرجَ منها وهو مرتاح."},{"bg":"desert","scene":["🐕","💧","🕳️"],"text":"وعندما خرجَ من البئر، رأى كلبًا يلهثُ، يأكلُ الترابَ الرطبَ من شدّةِ العطش. نظرَ الرجلُ إليه، وفكّرَ في نفسِه، كما أخبرَنا النبيُّ صلّى اللهُ عليه وسلّم أنّه قال: «لقد بلغَ هذا الكلبَ من العطشِ مثلُ الذي كان بلغَ منّي». لقد شعرَ الرجلُ بالكلب، لأنّه كان عطشانَ مثلَه قبلَ قليل."},{"bg":"desert","scene":["🚶","👞","💧"],"text":"فماذا فعلَ الرجل؟ نزلَ إلى البئرِ مرّةً أخرى، وملأَ خُفَّه ماءً، والخفُّ نوعٌ من الأحذيةِ الجلديّة، ثم أمسكَه بفمِه حتّى يستطيعَ أنْ يصعدَ بيديه، ثم سقى الكلبَ حتّى شرب. عملٌ صغير، لكنّه مليءٌ بالرحمة."},{"bg":"night","scene":["🤲","✨","🌙"],"text":"وأخبرَنا النبيُّ صلّى اللهُ عليه وسلّم أنَّ اللهَ شكرَ لهذا الرجلِ عملَه، فغفرَ له. فتعجّبَ الصحابةُ وسألوا: يا رسولَ الله، وإنَّ لنا في البهائمِ لأجرًا؟ فقال صلّى اللهُ عليه وسلّم: «في كلِّ كبدٍ رطبةٍ أجر». يعني: في الإحسانِ إلى كلِّ مخلوقٍ حيٍّ أجرٌ وثواب."},{"bg":"night","scene":["🐦","💧","💤"],"text":"هل رأيتَ يا صغيري؟ قطرةُ ماءٍ لحيوانٍ عطشان يحبُّها الله. فإذا رأيتَ قطّةً جائعة، أو عصفورًا عطشانَ في يومٍ حارّ، فتذكّرْ هذه القصّة، وكنْ رحيمًا. والآن أغمضْ عينيك، وقلْ: اللهمَّ اجعلْني من الرحماء. تصبحُ على خيرٍ يا صغيري الرحيم."}],"question":{"q":"كيف سقى الرجلُ الكلبَ العطشان؟","options":["ملأَ خفَّه ماءً من البئر","تركَه وذهب","أعطاه طعامًا فقط"],"answer":0},"activity":"ضعْ مع أهلِك صحنًا صغيرًا فيه ماءٌ للعصافيرِ في الشرفةِ أو الحديقة."},
{"id":"h02-anas","sort":120,"title":"أنسٌ والنبيُّ الرحيم","emoji":"🌴","value_code":"manners","value_name":"حُسنُ التعامل","kind":"hadith","minutes":4,"source":"صحيح البخاري (6038، 6911) وصحيح مسلم (2309، 2310)، عن أنس بن مالك رضي الله عنه","min_grade":1,"max_grade":12,"pages":[{"bg":"desert","scene":["🌴","🕌","✨"],"text":"يا صغيري، هل تعرفُ الصحابيَّ أنسَ بنَ مالكٍ رضي الله عنه؟ كان أنسٌ ولدًا صغيرًا حين وصلَ النبيُّ صلّى اللهُ عليه وسلّم إلى المدينةِ المنوّرة. وقد حكى لنا أنسٌ بنفسِه قصصًا جميلةً عن أخلاقِ النبيِّ صلّى اللهُ عليه وسلّم، وهذه واحدةٌ منها."},{"bg":"desert","scene":["👦","🧔","🌴"],"text":"روى أنسٌ أنَّ أبا طلحةَ رضي الله عنه أخذَه بيدِه، وذهبَ به إلى رسولِ اللهِ صلّى اللهُ عليه وسلّم، وقال: يا رسولَ الله، «إنَّ أنسًا غلامٌ كيِّسٌ فليخدمْك». والكيِّسُ يعني الذكيَّ الفطن. فصارَ أنسٌ يخدمُ النبيَّ صلّى اللهُ عليه وسلّم، ويعيشُ قريبًا منه، ويتعلّمُ منه."},{"bg":"desert","scene":["👦","💛","📿"],"text":"وقال أنسٌ رضي الله عنه: «خدمتُ النبيَّ صلّى اللهُ عليه وسلّم عشرَ سنين، فما قال لي: أُفٍّ، ولا: لِمَ صنعتَ؟ ولا: ألا صنعتَ». تخيّلْ يا صغيري، عشرَ سنواتٍ كاملة، ولم يقلْ له النبيُّ صلّى اللهُ عليه وسلّم كلمةً تُحزنُه أبدًا. وقال أنسٌ أيضًا: كان رسولُ اللهِ صلّى اللهُ عليه وسلّم من أحسنِ الناسِ خُلُقًا."},{"bg":"desert","scene":["👦","👦🏽","🏪"],"text":"وحكى أنسٌ أنَّ النبيَّ صلّى اللهُ عليه وسلّم أرسلَه يومًا في حاجة، فخرجَ أنسٌ، فمرَّ على صبيانٍ يلعبون في السوق، فوقفَ عندهم. فإذا برسولِ اللهِ صلّى اللهُ عليه وسلّم قد أمسكَ بقفاه من ورائِه بلطف. قال أنس: فنظرتُ إليه وهو يضحك."},{"bg":"desert","scene":["🧔","😊","👦"],"text":"فقال له النبيُّ صلّى اللهُ عليه وسلّم بلطف: «يا أُنَيْس، أذهبتَ حيثُ أمرتُك؟» وأُنَيْس اسمُ تدليلٍ لأنس، كما نقولُ نحن للصغيرِ كلمةً حنونة. فقال أنس: «نعم، أنا أذهبُ يا رسولَ الله». لم يغضبْ النبيُّ صلّى اللهُ عليه وسلّم، بل ضحكَ وذكّرَه بلطفٍ ومحبّة."},{"bg":"night","scene":["🌙","💛","💤"],"text":"هذا هو حسنُ التعامل يا صغيري: أنْ نتكلّمَ بلطف، وأنْ نبتسم، وأنْ نصبرَ على مَن يخطئ، وأنْ ننصحَ برفق. وقدوتُنا في ذلك نبيُّنا محمّدٌ صلّى اللهُ عليه وسلّم. فغدًا، حاولْ أنْ تكلّمَ إخوتَك وأصدقاءَك بلطفٍ مثلَه. والآن نمْ هادئًا، وقلْ: اللهمَّ صلِّ على محمّد. تصبحُ على خيرٍ يا صغيري اللطيف."}],"question":{"q":"كم سنةً خدمَ أنسٌ النبيَّ صلّى اللهُ عليه وسلّم؟","options":["سنتين","عشرَ سنين","خمسَ سنين"],"answer":1},"activity":"حاولْ غدًا ألّا تقولَ «أُفّ» لأحد، وأنْ تنصحَ أخاك أو صديقَك بلطفٍ وابتسامة."},
{"id":"h03-abdurrahman","sort":130,"title":"الأخوّةُ في المدينة","emoji":"🤝","value_code":"help","value_name":"مساعدةُ الآخرين","kind":"hadith","minutes":3,"source":"صحيح البخاري (2048، 3780)، عن عبد الرحمن بن عوف وأنس بن مالك رضي الله عنهما","min_grade":1,"max_grade":12,"pages":[{"bg":"desert","scene":["🐪","🌴","🏘️"],"text":"يا صغيري، عندما هاجرَ المسلمون من مكّةَ إلى المدينةِ المنوّرة، تركوا بيوتَهم وأموالَهم هناك. وكان أهلُ المدينة، واسمُهم الأنصار، يستقبلونهم بمحبّة. وآخى النبيُّ صلّى اللهُ عليه وسلّم بين المهاجرين والأنصار، يعني جعلَ كلَّ واحدٍ منهم أخًا لصاحبِه."},{"bg":"desert","scene":["🧔","🤝","🧔🏽"],"text":"وكان من هؤلاءِ الإخوة: عبدُ الرحمنِ بنُ عوفٍ من المهاجرين، وسعدُ بنُ الربيعِ من الأنصار، رضي الله عنهما. وكان سعدٌ من أكثرِ الأنصارِ مالًا، فقال لأخيه عبدِ الرحمن: إنّي أكثرُ الأنصارِ مالًا، فأَقسِمُ لك نصفَ مالي. انظرْ يا صغيري كم كان سعدٌ كريمًا، يريدُ أنْ يساعدَ أخاه بنصفِ ما يملك!"},{"bg":"desert","scene":["🧔","💬","🏪"],"text":"فماذا قال عبدُ الرحمن؟ قال له كلامًا جميلًا: «باركَ اللهُ لك في أهلِك ومالِك، أين سوقُكم؟» يعني: شكرًا لك يا أخي، أدعو اللهَ أنْ يباركَ لك، ولكنْ دلَّني على السوقِ لأعملَ وأكسبَ رزقي بنفسي."},{"bg":"desert","scene":["🧀","🫙","🏪"],"text":"فدلّوه على السوق، فذهبَ عبدُ الرحمنِ يبيعُ ويشتري، وتاجرَ في الأَقِطِ والسمن، والأقطُ نوعٌ من اللبنِ المجفّف. ورجعَ في آخرِ اليومِ وقد ربحَ شيئًا منهما. واستمرَّ يعملُ بجدٍّ، وباركَ اللهُ له في تجارتِه حتّى صارَ من الأغنياء."},{"bg":"night","scene":["💛","🤝","🌙"],"text":"في هذه القصّةِ درسان جميلان يا صغيري: سعدٌ علّمَنا أنْ نساعدَ الآخرين ونكرمَهم بما نملك، وعبدُ الرحمنِ علّمَنا أنْ نشكرَ مَن يساعدُنا، وأنْ نعملَ ونجتهد. فكنْ يا صغيري كريمًا مثلَ سعد، ومجتهدًا مثلَ عبدِ الرحمن. والآن نمْ هادئًا، تصبحُ على خيرٍ يا صغيري الكريم."}],"question":{"q":"ماذا طلبَ عبدُ الرحمنِ من أخيه سعد؟","options":["نصفَ مالِه","أنْ يدلَّه على السوق","بيتًا كبيرًا"],"answer":1},"activity":"شاركْ أخاك أو صديقَك شيئًا تحبُّه غدًا، مثلَ لعبةٍ أو قطعةِ حلوى، وقلْ له كلمةً طيّبة."},
{"id":"h04-ibn-abbas","sort":140,"title":"وصيّةٌ لغلامٍ صغير","emoji":"🌟","value_code":"tawakkul","value_name":"الثقةُ بالله","kind":"hadith","minutes":3,"source":"سنن الترمذي (2516) وقال: حديث حسن صحيح، عن عبد الله بن عباس رضي الله عنهما","min_grade":1,"max_grade":12,"pages":[{"bg":"night","scene":["👦","🐪","✨"],"text":"يا صغيري، كان عبدُ اللهِ بنُ عبّاسٍ رضي الله عنهما ابنَ عمِّ النبيِّ صلّى اللهُ عليه وسلّم، وكان غلامًا صغيرًا ذكيًّا يحبُّ العلم. وقد حكى لنا أنّه كان يومًا خلفَ رسولِ اللهِ صلّى اللهُ عليه وسلّم، فقال له النبيُّ صلّى اللهُ عليه وسلّم كلماتٍ جميلة، حفظَها ابنُ عبّاس، وبقيَ الناسُ يحفظونها إلى اليوم."},{"bg":"night","scene":["🧔","💬","👦"],"text":"قال له النبيُّ صلّى اللهُ عليه وسلّم: «يا غلام، إنّي أعلّمُك كلمات». تخيّلْ يا صغيري كم فرحَ ابنُ عبّاس، وكيف أنصتَ باهتمام، لأنَّ النبيَّ صلّى اللهُ عليه وسلّم سيعلّمُه شيئًا خاصًّا. فقال له: «احفظِ اللهَ يحفظْك»."},{"bg":"night","scene":["🛡️","💛","🌙"],"text":"ومعنى «احفظِ اللهَ يحفظْك» يا صغيري: أنْ تطيعَ اللهَ وتفعلَ ما يحبُّ، مثلَ الصلاةِ والصدقِ وبرِّ الوالدين، فيحفظُك اللهُ ويرعاك. ثم قال له: «احفظِ اللهَ تجدْه تُجاهَك»، يعني تجدُ اللهَ معك يعينُك ويساعدُك في كلِّ مكان."},{"bg":"night","scene":["🤲","✨","⭐"],"text":"ثم قال له: «إذا سألتَ فاسألِ الله، وإذا استعنتَ فاستعنْ بالله». يعني يا صغيري: إذا احتجتَ شيئًا فاطلبْه من اللهِ وادعُه، وإذا أردتَ أنْ تفعلَ شيئًا صعبًا، مثلَ امتحانٍ أو حفظِ درس، فقلْ: يا ربِّ أعنّي. فاللهُ قريبٌ يسمعُ دعاءَك."},{"bg":"night","scene":["👦","🛏️","🌙"],"text":"هذه الكلماتُ تجعلُ القلبَ مطمئنًّا وشجاعًا، فأنتَ لستَ وحدَك أبدًا، اللهُ معك يحفظُك في نومِك وفي يقظتِك. والآن، قبلَ أنْ تنام، ارفعْ يديك الصغيرتين وقلْ: يا ربِّ احفظْني واحفظْ أهلي، وأعنّي على كلِّ خير. ثم أغمضْ عينيك مطمئنًّا. تصبحُ على خيرٍ يا صغيري، في حفظِ اللهِ ورعايتِه."}],"question":{"q":"ماذا قال النبيُّ صلّى اللهُ عليه وسلّم لابنِ عبّاس؟","options":["احفظِ اللهَ يحفظْك","العبْ كثيرًا","لا تذهبْ إلى السوق"],"answer":0},"activity":"احفظْ مع أهلِك الجملةَ الأولى: «احفظِ اللهَ يحفظْك»، ورددْها قبلَ النومِ ثلاثَ مرّات."},
{"id":"p04-adam","sort":150,"title":"سيدنا آدم عليه السلام أبو البشر","emoji":"🌍","value_code":"tawba","value_name":"التوبة والاعتراف بالخطأ","kind":"prophet","minutes":3,"source":"القرآن الكريم: البقرة 30-38، الأعراف 11-25، طه 115-123، ص 71-76","min_grade":1,"max_grade":12,"pages":[{"bg":"garden","scene":["🌍","✨","🌤️"],"text":"يا صغيري، هذه قصّةُ أوّلِ إنسانٍ خلقَه الله، أبينا آدمَ عليه السلام. قبلَ أنْ يخلقَه، أخبرَ اللهُ الملائكةَ فقال: «إني جاعل في الأرض خليفة» (البقرة 30)، يعني سيجعلُ في الأرضِ ناسًا يعيشون فيها ويعمرونها جيلًا بعدَ جيل."},{"bg":"garden","scene":["🟤","✨","💫"],"text":"وخلقَ اللهُ آدمَ من طين، قال تعالى: «إني خالق بشرا من طين» (ص 71). ثمَّ علّمَه اللهُ أسماءَ الأشياء: «وعلم آدم الأسماء كلها» (البقرة 31). فعرفَ آدمُ أسماءَ ما حولَه، فكانَ العلمُ من أوّلِ النِّعَمِ التي أكرمَ اللهُ بها الإنسان."},{"bg":"garden","scene":["✨","🌟","⭐"],"text":"وأمرَ اللهُ الملائكةَ أنْ يسجدوا لآدمَ سجودَ تحيّةٍ وإكرام، فسجدوا طاعةً لله، إلّا إبليس، قال تعالى: «أبى واستكبر» (البقرة 34). يعني رفضَ وتكبّر، وظنَّ أنّه أفضلُ من آدم. والتكبّرُ يا صغيري صفةٌ لا يحبُّها الله."},{"bg":"garden","scene":["🌳","🌸","🏞️"],"text":"وأسكنَ اللهُ آدمَ وزوجَه الجنّة، وقال: «يا آدم اسكن أنت وزوجك الجنة وكلا منها رغدا حيث شئتما ولا تقربا هذه الشجرة» (البقرة 35). كلُّ شيءٍ في الجنّةِ مسموحٌ لهما، إلّا شجرةً واحدة. لكنَّ الشيطانَ وسوسَ لهما، فنسيا الوصيّةَ وأكلا من الشجرة."},{"bg":"dusk","scene":["💧","💗","✨"],"text":"فحزنَ آدمُ وزوجُه، ولم يَلُوما غيرَهما، بل اعترفا بخطئهما ورجعا إلى الله، فقالا: «ربنا ظلمنا أنفسنا وإن لم تغفر لنا وترحمنا لنكونن من الخاسرين» (الأعراف 23). فقبلَ اللهُ توبتَهما، قال تعالى: «فتلقى آدم من ربه كلمات فتاب عليه إنه هو التواب الرحيم» (البقرة 37)."},{"bg":"night","scene":["🌍","🌙","✨"],"text":"ثمَّ أنزلَ اللهُ آدمَ وزوجَه إلى الأرض، ووعدَ مَن يتّبعُ هُداه بالخير: «فمن تبع هداي فلا خوف عليهم ولا هم يحزنون» (البقرة 38). تعلّمْنا يا صغيري أنَّ كلَّ إنسانٍ يخطئ، وأنَّ الشجاعَ هو الذي يعترفُ بخطئه ويقولُ: أستغفرُ الله. قلْها الآن، ثمَّ نمْ مطمئنًّا. تصبحُ على خير."}],"question":{"q":"ماذا فعلَ آدمُ عليه السلام بعدَ أنْ أخطأ؟","options":["لامَ غيرَه","اعترفَ بخطئه وطلبَ المغفرةَ من الله","سكتَ ولم يفعلْ شيئًا"],"answer":1},"activity":"إذا أخطأتَ اليومَ في شيء، فقلْ: «ربنا ظلمنا أنفسنا» (الأعراف 23)، واعتذرْ لمن أخطأتَ في حقِّه بكلمةٍ طيّبة."},
{"id":"p05-idris","sort":160,"title":"سيدنا إدريس عليه السلام","emoji":"📜","value_code":"sidq","value_name":"الصدق والصبر","kind":"prophet","minutes":3,"source":"القرآن الكريم: مريم 56-57، الأنبياء 85-86","min_grade":1,"max_grade":12,"pages":[{"bg":"night","scene":["📜","⭐","🌙"],"text":"يا صغيري، هذه الليلةَ نتعرّفُ على نبيٍّ كريم اسمُه إدريسُ عليه السلام. ذكرَه اللهُ في القرآنِ الكريمِ في موضعين، ولم يخبرْنا القرآنُ بتفاصيلِ حياتِه، لكنّه أخبرَنا بصفاتٍ جميلةٍ كانت فيه، تعالَ نتعرّفْ عليها معًا."},{"bg":"night","scene":["💎","✨","📜"],"text":"قال اللهُ تعالى: «واذكر في الكتاب إدريس إنه كان صديقا نبيا» (مريم 56). والصِّدّيقُ يا صغيري هو الذي يكونُ صادقًا دائمًا، في كلامِه وفي أفعالِه وفي وعودِه. فكانَ إدريسُ عليه السلام صادقًا جدًّا، وكان نبيًّا من أنبياءِ الله."},{"bg":"dusk","scene":["⛰️","🌟","☁️"],"text":"ثمَّ قال تعالى: «ورفعناه مكانا عليا» (مريم 57). يعني أنَّ اللهَ أعطاه منزلةً عاليةً ومكانةً رفيعة. فمَن يصدقُ ويطيعُ الله، يرفعُ اللهُ قدرَه ويحبُّه."},{"bg":"garden","scene":["🌱","🌳","🌸"],"text":"وذكرَه اللهُ مع أنبياءَ آخرين صبروا على طاعتِه، فقال: «وإسماعيل وإدريس وذا الكفل كل من الصابرين» (الأنبياء 85). ثمَّ قال: «وأدخلناهم في رحمتنا إنهم من الصالحين» (الأنبياء 86). فكانَ إدريسُ صابرًا وصالحًا، والصبرُ مثلُ البذرة، نصبرُ عليها فتصبحُ شجرةً جميلة."},{"bg":"night","scene":["🌙","✨","💎"],"text":"هذا ما أخبرَنا به القرآنُ عن سيدنا إدريسَ عليه السلام: صادقٌ، صابرٌ، صالحٌ، رفعَ اللهُ مكانتَه. وهذه صفاتٌ نستطيعُ نحنُ أيضًا أنْ نتعلّمَها. فكنْ يا صغيري صادقًا في كلامِك، صابرًا في دروسِك، طيّبًا مع أهلِك. تصبحُ على خيرٍ في رحمةِ الله."}],"question":{"q":"ما معنى أنَّ إدريسَ عليه السلام كان صِدّيقًا؟","options":["كان صادقًا دائمًا","كان يحبُّ اللعب","كان يسافرُ كثيرًا"],"answer":0},"activity":"اختر صفةً من صفاتِ سيدنا إدريس (الصدق، الصبر، الصلاح)، وحاولْ أنْ تعملَ بها غدًا، ثمَّ أخبرْ أهلَك كيف فعلت."},
{"id":"p02-nuh","sort":170,"title":"سيدنا نوح عليه السلام والسفينة","emoji":"🚢","value_code":"sabr","value_name":"الصبر","kind":"prophet","minutes":4,"source":"القرآن الكريم: هود 25-48، نوح 1-28، العنكبوت 14، القمر 9-15","min_grade":1,"max_grade":12,"pages":[{"bg":"garden","scene":["🏘️","🌳","☁️"],"text":"يا صغيري، هذه قصّةُ نبيِّ اللهِ نوحٍ عليه السلام كما جاءت في القرآنِ الكريم. أرسلَه اللهُ إلى قومِه يدعوهم إلى عبادةِ اللهِ وحدَه. وكان صبورًا جدًّا، فقد بقيَ يدعوهم زمنًا طويلًا، قال تعالى: «فلبث فيهم ألف سنة إلا خمسين عاما» (العنكبوت 14)."},{"bg":"garden","scene":["🌙","☀️","💬"],"text":"دعاهم في الليلِ والنهار، كما أخبرَنا القرآن: «قال رب إني دعوت قومي ليلا ونهارا» (نوح 5)، وقال لهم: «استغفروا ربكم إنه كان غفارا» (نوح 10). لكنَّ أكثرَهم لم يستجيبوا، قال تعالى: «وما آمن معه إلا قليل» (هود 40). ومع ذلك لم ييأسْ نوحٌ عليه السلام، وبقيَ صابرًا."},{"bg":"garden","scene":["🪵","🔨","🚢"],"text":"فأمرَه اللهُ أنْ يصنعَ سفينةً كبيرة: «واصنع الفلك بأعيننا ووحينا» (هود 37). والفلكُ هو السفينة. فبدأ يصنعُها كما أمرَه الله، وكان بعضُ قومِه يمرّون ويسخرون منه، قال تعالى: «وكلما مر عليه ملأ من قومه سخروا منه» (هود 38). لكنّه استمرَّ في عملِه بصبرٍ وثقةٍ بالله."},{"bg":"sea","scene":["🦁","🐘","🕊️"],"text":"ولمّا جاءَ أمرُ الله، قال تعالى لنوحٍ عليه السلام: «احمل فيها من كل زوجين اثنين» (هود 40)، أي من كلِّ نوعٍ من الحيواناتِ ذكرًا وأنثى، ومعه أهلُه والذين آمنوا. فقال لهم نوحٌ عليه السلام: «اركبوا فيها بسم الله مجراها ومرساها إن ربي لغفور رحيم» (هود 41)."},{"bg":"sea","scene":["🌧️","🌊","🚢"],"text":"ثمَّ نزلَ المطرُ من السماء، وتفجّرتِ العيونُ من الأرض، وارتفعَ الماءُ كثيرًا، والسفينةُ تجري بأمرِ اللهِ وحفظِه، ومَن فيها في أمانٍ. ثمَّ قال اللهُ: «يا أرض ابلعي ماءك ويا سماء أقلعي» (هود 44)، فهدأَ الماء، ورستِ السفينةُ على جبلٍ اسمُه الجوديّ: «واستوت على الجودي» (هود 44)."},{"bg":"night","scene":["⛰️","🚢","🕊️"],"text":"ونزلَ نوحٌ عليه السلام ومَن معه إلى الأرضِ بسلام، قال تعالى: «قيل يا نوح اهبط بسلام منا وبركات عليك» (هود 48). تعلّمْنا يا صغيري من سيدنا نوحٍ عليه السلام الصبرَ، وألّا نيأسَ أبدًا، وأنْ نثقَ بأنَّ اللهَ يحفظُ عبادَه المؤمنين. تصبحُ على خيرٍ في أمانِ الله."}],"question":{"q":"ماذا صنعَ نوحٌ عليه السلام بأمرِ الله؟","options":["بيتًا من الصخر","سفينةً كبيرة","حديقةً جميلة"],"answer":1},"activity":"ارسمْ مع أهلِك سفينةً وحولَها أزواجٌ من الحيوانات، وتحدّثوا عن معنى الصبر."},
{"id":"p06-hud","sort":180,"title":"سيدنا هود عليه السلام وقوم عاد","emoji":"🌬️","value_code":"shukr","value_name":"شكر النعم والتوكل على الله","kind":"prophet","minutes":3,"source":"القرآن الكريم: هود 50-60، الشعراء 123-140، الأحقاف 21-25، فصلت 15","min_grade":1,"max_grade":12,"pages":[{"bg":"desert","scene":["🏜️","🏛️","⛰️"],"text":"يا صغيري، هذه قصّةُ نبيِّ اللهِ هودٍ عليه السلام. أرسلَه اللهُ إلى قومٍ اسمُهم عاد، كانوا يسكنون في مكانٍ فيه تلالٌ من الرمال اسمُه الأحقاف، قال تعالى: «واذكر أخا عاد إذ أنذر قومه بالأحقاف» (الأحقاف 21)."},{"bg":"desert","scene":["🏛️","🌴","🐄"],"text":"وكان قومُ عادٍ أقوياءَ جدًّا، يبنون المباني العالية، وأعطاهم اللهُ نِعَمًا كثيرة، قال تعالى على لسانِ هود: «أمدكم بأنعام وبنين وجنات وعيون» (الشعراء 133-134). لكنّهم اغترّوا بقوّتِهم، وقالوا: «من أشد منا قوة» (فصلت 15)، ونسوا أنَّ اللهَ هو الذي أعطاهم هذه القوّة."},{"bg":"desert","scene":["💬","☁️","🌧️"],"text":"فنصحَهم هودٌ عليه السلام بلطف: «يا قوم اعبدوا الله ما لكم من إله غيره» (هود 50). ووعدَهم بالخيرِ إنْ رجعوا إلى الله: «ويا قوم استغفروا ربكم ثم توبوا إليه يرسل السماء عليكم مدرارا ويزدكم قوة إلى قوتكم» (هود 52). يعني ينزلُ عليكم المطرُ الكثير، ويزيدُكم قوّة."},{"bg":"dusk","scene":["⛰️","🏔️","✨"],"text":"لكنَّ أكثرَهم رفضوا النصيحة. ولم يخفْ هودٌ عليه السلام منهم، لأنّه كان واثقًا بربِّه، فقال لهم: «إني توكلت على الله ربي وربكم» (هود 56). والتوكّلُ يا صغيري أنْ نعملَ ما علينا، ثمَّ نثقَ بأنَّ اللهَ معنا ولن يضيّعَنا."},{"bg":"desert","scene":["🌬️","☁️","🏜️"],"text":"ولمّا أصرّوا على العناد، جاءهم عقابُ اللهِ بريحٍ شديدة. أمّا هودٌ والذين آمنوا معه فقد حفظَهم الله، قال تعالى: «ولما جاء أمرنا نجينا هودا والذين آمنوا معه برحمة منا» (هود 58). فاللهُ دائمًا يحفظُ عبادَه المؤمنين."},{"bg":"night","scene":["🌙","✨","🌧️"],"text":"تعلّمْنا يا صغيري من قصّةِ سيدنا هودٍ عليه السلام أنَّ كلَّ قوّةٍ عندَنا هي من الله، فنشكرُه عليها ولا نتكبّر، وأنَّ الاستغفارَ يجلبُ الخيرَ والبركة، وأنَّ المؤمنَ يتوكّلُ على ربِّه. قلْ معي: أستغفرُ الله، الحمدُ لله. تصبحُ على خير."}],"question":{"q":"ماذا قال هودٌ عليه السلام لقومِه عن الاستغفار؟","options":["إنّه يجلبُ المطرَ والقوّة","إنّه غيرُ مهمّ","إنّه للكبارِ فقط"],"answer":0},"activity":"قبلَ النوم، عدَّ مع أهلِك خمسَ نِعَمٍ أعطاك اللهُ إيّاها (مثل القوّة والصحّة)، وقولوا بعدَ كلِّ واحدة: الحمدُ لله."},
{"id":"p01-saleh","sort":190,"title":"سيدنا صالح عليه السلام والناقة","emoji":"🐪","value_code":"obey","value_name":"طاعة الله والرفق بالحيوان","kind":"prophet","minutes":4,"source":"القرآن الكريم: الأعراف 73-79، هود 61-68، الشعراء 141-159، الشمس 11-15","min_grade":1,"max_grade":12,"pages":[{"bg":"desert","scene":["⛰️","🏠","🌴"],"text":"يا صغيري، هذه الليلةَ نتعرّفُ على قصّةٍ من القرآنِ الكريم، قصّةِ نبيِّ اللهِ صالحٍ عليه السلام. كان يعيشُ مع قومٍ اسمُهم ثمود. أعطاهم اللهُ نِعَمًا كثيرة: بساتين وعيونَ ماءٍ ونخيلًا، وكانوا ماهرين جدًّا، كما قال اللهُ تعالى عنهم: «وتنحتون الجبال بيوتا» (الأعراف 74)، أي يصنعون بيوتَهم في الصخر."},{"bg":"desert","scene":["🌴","🌾","💧"],"text":"أرسلَ اللهُ إليهم صالحًا عليه السلام يدعوهم إلى عبادةِ اللهِ وحدَه وشكرِه على نِعَمِه، فقال لهم كما في القرآن: «يا قوم اعبدوا الله ما لكم من إله غيره» (الأعراف 73). فآمنَ به بعضُ الناس، وبقيَ آخرون لا يريدون أنْ يسمعوا النصيحة."},{"bg":"desert","scene":["🐪","✨","⛰️"],"text":"فجعلَ اللهُ لهم آيةً عظيمة، أي علامةً تدلُّ على صدقِ نبيِّه: ناقةً مباركة. قال صالحٌ عليه السلام: «هذه ناقة الله لكم آية فذروها تأكل في أرض الله ولا تمسوها بسوء» (الأعراف 73). أي اتركوها تأكلُ وتشربُ بسلام، ولا تؤذوها أبدًا."},{"bg":"desert","scene":["💧","🐪","📅"],"text":"وكان الماءُ في بلدِهم مقسومًا بالعدل، يومٌ تشربُ فيه الناقة، ويومٌ يشربُ فيه الناس. قال تعالى: «قال هذه ناقة لها شرب ولكم شرب يوم معلوم» (الشعراء 155). وهذا درسٌ جميل يا صغيري: أنْ نتقاسمَ النِّعمَ بالعدل، وأنْ نحترمَ الاتفاقَ ونرفقَ بالحيوان."},{"bg":"dusk","scene":["🌙","🐪","⛰️"],"text":"لكنَّ الذين لم يؤمنوا لم يحفظوا الوصيّة، وآذوا الناقة وعصَوا أمرَ الله، فنزلَ بهم عقابٌ من الله. أمّا صالحٌ عليه السلام والذين آمنوا معه فقد نجّاهم اللهُ برحمتِه، كما قال تعالى: «فلما جاء أمرنا نجينا صالحا والذين آمنوا معه برحمة منا» (هود 66)."},{"bg":"night","scene":["🌙","✨","🐪"],"text":"تعلّمْنا من قصّةِ سيدنا صالحٍ عليه السلام أنْ نطيعَ اللهَ ونشكرَه على نِعَمِه، وأنْ نحافظَ على الوعد، وأنْ نرحمَ الحيواناتِ ولا نؤذيها. والآن أغمضْ عينيك يا صغيري، وقلْ: الحمدُ للهِ على نِعَمِه. تصبحُ على خيرٍ في حفظِ الله."}],"question":{"q":"ما الآيةُ التي جعلَها اللهُ لقومِ صالحٍ عليه السلام؟","options":["ناقةٌ مباركة","سفينةٌ كبيرة","نجمةٌ لامعة"],"answer":0},"activity":"ضعْ مع أهلِك صحنَ ماءٍ للعصافيرِ أو القطط، وتذكّرْ أنَّ الرفقَ بالحيوانِ يحبُّه الله."},
{"id":"p03-ibrahim","sort":200,"title":"سيدنا إبراهيم عليه السلام والنار","emoji":"🔥","value_code":"tawakkul","value_name":"الثقةُ بالله","kind":"prophet","minutes":4,"source":"القرآن الكريم: الأنبياء 51-71، الصافات 83-98","min_grade":1,"max_grade":12,"pages":[{"bg":"night","scene":["⭐","🌙","☀️"],"text":"يا صغيري، هذه قصّةُ نبيِّ اللهِ إبراهيمَ عليه السلام من القرآنِ الكريم. كان إبراهيمُ منذُ صغرِه ذكيًّا يفكّرُ ويتأمّل، قال تعالى: «ولقد آتينا إبراهيم رشده من قبل» (الأنبياء 51)، أي أعطاه اللهُ الفهمَ والهدايةَ وهو صغير، فعرفَ أنَّ اللهَ وحدَه هو الخالقُ المستحقُّ للعبادة."},{"bg":"desert","scene":["🗿","🗿","🗿"],"text":"وكان قومُه يعبدون تماثيلَ صنعوها بأيديهم، لا تسمعُ ولا تتكلّم. فسألهم إبراهيمُ عليه السلام: «ما هذه التماثيل التي أنتم لها عاكفون» (الأنبياء 52)؟ فقالوا: «وجدنا آباءنا لها عابدين» (الأنبياء 53). فأخبرَهم أنَّ هذا خطأ، وأنَّ العبادةَ لا تكونُ إلّا لله."},{"bg":"desert","scene":["🪓","🗿","💭"],"text":"وأرادَ أنْ يُفهمَهم بطريقةٍ ذكيّة أنَّ التماثيلَ لا تنفعُ شيئًا، فكسّرَها إلّا الكبيرَ منها، قال تعالى: «فجعلهم جذاذا إلا كبيرا لهم لعلهم إليه يرجعون» (الأنبياء 58). ولمّا سألوه، قال: «بل فعله كبيرهم هذا فاسألوهم إن كانوا ينطقون» (الأنبياء 63)، ليعرفوا بأنفسِهم أنَّها لا تتكلّمُ ولا تدافعُ عن نفسِها."},{"bg":"dusk","scene":["🔥","🪵","🌫️"],"text":"فقال لهم: «أفتعبدون من دون الله ما لا ينفعكم شيئا ولا يضركم» (الأنبياء 66). لكنّهم بدلَ أنْ يفكّروا، غضبوا وقرّروا أنْ يلقوه في نارٍ عظيمة. وكان إبراهيمُ عليه السلام واثقًا بربِّه تمامًا، يعلمُ أنَّ اللهَ معه ولن يتركَه."},{"bg":"garden","scene":["🔥","❄️","🌸"],"text":"وهنا جاءتْ رحمةُ الله، فقال اللهُ تعالى: «قلنا يا نار كوني بردا وسلاما على إبراهيم» (الأنبياء 69). فأطاعتِ النارُ أمرَ ربِّها، وصارتْ بردًا وسلامًا عليه، ولم تؤذِه أبدًا. سبحانَ اللهِ القادرِ على كلِّ شيء! وقال تعالى: «وأرادوا به كيدا فجعلناهم الأخسرين» (الأنبياء 70)."},{"bg":"night","scene":["🌙","✨","🌸"],"text":"تعلّمْنا يا صغيري من سيدنا إبراهيمَ عليه السلام أنْ نعبدَ اللهَ وحدَه، وأنْ نقولَ الحقَّ بأدبٍ وحكمة، وأنْ نثقَ بأنَّ اللهَ يحفظُ مَن يتوكّلُ عليه. والآن أغمضْ عينيك وقلْ: حسبيَ اللهُ ونعمَ الوكيل. تصبحُ على خيرٍ في حفظِ الله ورعايتِه."}],"question":{"q":"ماذا قالَ اللهُ تعالى للنار؟","options":["اشتعلي أكثر","كوني بردا وسلاما على إبراهيم","انطفئي غدًا"],"answer":1},"activity":"احفظْ مع أهلِك الآية: «يا نار كوني بردا وسلاما على إبراهيم» (الأنبياء 69)، واسألْهم عن معنى التوكّل على الله."},
{"id":"p07-lut","sort":210,"title":"سيدنا لوط عليه السلام","emoji":"🌌","value_code":"haqq","value_name":"الثبات على الحق","kind":"prophet","minutes":3,"source":"القرآن الكريم: الأنبياء 71-75، العنكبوت 26-35، هود 77-81، الذاريات 31-36","min_grade":1,"max_grade":12,"pages":[{"bg":"desert","scene":["🐪","🌴","🛤️"],"text":"يا صغيري، كان لوطٌ عليه السلام من الذين آمنوا بدعوةِ سيدنا إبراهيمَ عليه السلام، قال تعالى: «فآمن له لوط» (العنكبوت 26). وهاجرَ معه في سبيلِ الله، وأكرمَه اللهُ فقال: «ولوطا آتيناه حكما وعلما» (الأنبياء 74)، أي أعطاه الحكمةَ والعلم، وجعلَه نبيًّا."},{"bg":"city","scene":["🏘️","💬","🌇"],"text":"وأرسلَه اللهُ إلى قومٍ كانوا يفعلون أعمالًا سيّئةً قبيحة، ويؤذون الناس. فنصحَهم لوطٌ عليه السلام كثيرًا أنْ يتّقوا اللهَ ويتركوا السوء، لكنّهم لم يسمعوا له، فدعا ربَّه: «رب انصرني على القوم المفسدين» (العنكبوت 30)."},{"bg":"city","scene":["✨","🏠","🌙"],"text":"فأرسلَ اللهُ إليه ملائكةً كرامًا، وطمأنوه وقالوا له: «يا لوط إنا رسل ربك لن يصلوا إليك» (هود 81). ثمَّ أمروه أنْ يخرجَ مع أهلِه المؤمنين في آخرِ الليل، وألّا يلتفتوا إلى الوراء."},{"bg":"night","scene":["🌌","⭐","🛤️"],"text":"فخرجَ لوطٌ عليه السلام ومَن آمنَ معه في هدوءِ الليل، والنجومُ فوقَهم، وهم واثقون بوعدِ الله. وحفظَهم الله، قال تعالى: «فأخرجنا من كان فيها من المؤمنين» (الذاريات 35). أمّا الذين أصرّوا على السوءِ فنزلَ بهم عقابُ الله."},{"bg":"night","scene":["🌙","✨","💎"],"text":"تعلّمْنا يا صغيري من سيدنا لوطٍ عليه السلام أنْ نثبتَ على الحقِّ ولو كان الذين حولَنا يفعلون الخطأ، وأنْ ننصحَ بلطف، وأنْ ندعوَ اللهَ إذا احتجْنا إليه، فهو ينصرُ المؤمنين ويحفظُهم. تصبحُ على خيرٍ في حفظِ الله."}],"question":{"q":"ماذا فعلَ لوطٌ عليه السلام عندما لم يسمعْ قومُه النصيحة؟","options":["فعلَ مثلَهم","دعا اللهَ أنْ ينصرَه","نسيَ النصيحة"],"answer":1},"activity":"إذا رأيتَ صديقًا يفعلُ شيئًا خطأً، فكّرْ مع أهلِك: كيف تنصحُه بكلمةٍ لطيفة؟"},
{"id":"p08-ismail","sort":220,"title":"سيدنا إسماعيل عليه السلام وبناء الكعبة","emoji":"🕋","value_code":"wafa","value_name":"الطاعة والوفاء بالوعد","kind":"prophet","minutes":3,"source":"القرآن الكريم: إبراهيم 37، الصافات 99-111، البقرة 125-129، مريم 54-55","min_grade":1,"max_grade":12,"pages":[{"bg":"desert","scene":["🏜️","⛰️","💧"],"text":"يا صغيري، إسماعيلُ عليه السلام هو ابنُ سيدنا إبراهيمَ عليه السلام. أسكنَه أبوه بأمرِ اللهِ مع أمِّه في وادٍ ليس فيه زرع، عندَ البيتِ الحرام، ودعا ربَّه: «ربنا إني أسكنت من ذريتي بواد غير ذي زرع عند بيتك المحرم» (إبراهيم 37)، ودعا أنْ يرزقَهم اللهُ من الثمرات، وأنْ يحبَّهم الناس."},{"bg":"desert","scene":["💭","⭐","🌙"],"text":"ولمّا كبرَ إسماعيلُ قليلًا، رأى أبوه في المنامِ أمرًا من اللهِ صعبًا جدًّا يتعلّقُ بابنِه، ورؤيا الأنبياءِ حقّ. فأخبرَه بها، فكانَ جوابُ إسماعيلَ جوابَ الابنِ المطيعِ الصابر: «يا أبت افعل ما تؤمر ستجدني إن شاء الله من الصابرين» (الصافات 102)."},{"bg":"garden","scene":["🐏","✨","🌸"],"text":"فلمّا أطاعا أمرَ اللهِ معًا، جاءَ الفرَجُ والرحمة، ففدى اللهُ إسماعيلَ بكبشٍ عظيم، قال تعالى: «وفديناه بذبح عظيم» (الصافات 107). ومن هنا يا صغيري نذبحُ الأضاحيَ في عيدِ الأضحى، ونفرحُ ونشكرُ الله."},{"bg":"desert","scene":["🧱","🕋","✨"],"text":"وأمرَ اللهُ إبراهيمَ وإسماعيلَ أنْ يبنيا الكعبة، فكانا يرفعان حجارتَها معًا ويدعوان: «ربنا تقبل منا إنك أنت السميع العليم» (البقرة 127). تخيّلْ يا صغيري: الأبُ والابنُ يعملان معًا في أعظمِ بيتٍ على الأرض، ويطلبان من اللهِ أنْ يقبلَ عملَهما."},{"bg":"night","scene":["🕋","🌙","✨"],"text":"ومدحَ اللهُ إسماعيلَ فقال: «إنه كان صادق الوعد وكان رسولا نبيا» (مريم 54). فإذا وعدَ وفى. تعلّمْنا يا صغيري من سيدنا إسماعيلَ عليه السلام طاعةَ الله، وبرَّ الوالدين، والوفاءَ بالوعد. تصبحُ على خيرٍ في حفظِ الله."}],"question":{"q":"ماذا بنى إبراهيمُ وإسماعيلُ عليهما السلام معًا؟","options":["سفينة","الكعبة","قصرًا كبيرًا"],"answer":1},"activity":"عِدْ أهلَك بشيءٍ صغيرٍ تستطيعُ فعلَه غدًا (مثلَ ترتيبِ سريرِك)، ثمَّ أوفِ بوعدِك مثلَ سيدنا إسماعيل."},
{"id":"p09-ishaq","sort":230,"title":"سيدنا إسحاق عليه السلام والبشارة","emoji":"🎁","value_code":"karam","value_name":"الكرم والشكر","kind":"prophet","minutes":3,"source":"القرآن الكريم: هود 69-73، الذاريات 24-30، الصافات 112-113، الأنبياء 72-73، إبراهيم 39","min_grade":1,"max_grade":12,"pages":[{"bg":"desert","scene":["🏡","🌴","✨"],"text":"يا صغيري، هذه قصّةُ بشارةٍ جميلة. كان سيدنا إبراهيمُ عليه السلام قد كبرَ في السنّ، وكذلك زوجتُه. وفي يومٍ جاءَه ضيوفٌ كرام، سلّموا عليه فردَّ عليهم السلام، ولم يكنْ يعرفُ أنّهم ملائكة، قال تعالى: «هل أتاك حديث ضيف إبراهيم المكرمين» (الذاريات 24)."},{"bg":"home","scene":["🍽️","🔥","🏡"],"text":"وكان إبراهيمُ كريمًا جدًّا، فأسرعَ إلى أهلِه وأحضرَ لضيوفِه طعامًا طيّبًا، قال تعالى: «فجاء بعجل سمين» (الذاريات 26). وقرّبَه إليهم بأدب. هكذا يا صغيري يكونُ إكرامُ الضيف: نسرعُ في خدمتِه ونقدّمُ له أطيبَ ما عندَنا."},{"bg":"home","scene":["🎁","⭐","💫"],"text":"ثمَّ أخبرَه الضيوفُ أنّهم ملائكةٌ أرسلَهم الله، وجاؤوا ببشارةٍ عظيمة: سيرزقُهما اللهُ ولدًا اسمُه إسحاق، وسيكونُ له ابنٌ اسمُه يعقوب، قال تعالى: «فبشرناها بإسحاق ومن وراء إسحاق يعقوب» (هود 71). فتعجّبتْ زوجتُه، كيف يكونُ لهما ولدٌ وهما كبيران؟"},{"bg":"garden","scene":["🌸","✨","🏡"],"text":"فقالت الملائكة: «أتعجبين من أمر الله رحمت الله وبركاته عليكم أهل البيت» (هود 73). يعني لا شيءَ صعبٌ على الله. وجاءَ إسحاقُ وصارَ نبيًّا صالحًا، قال تعالى: «وبشرناه بإسحاق نبيا من الصالحين» (الصافات 112)."},{"bg":"night","scene":["🌙","✨","🎁"],"text":"وشكرَ إبراهيمُ ربَّه فقال: «الحمد لله الذي وهب لي على الكبر إسماعيل وإسحاق» (إبراهيم 39). تعلّمْنا يا صغيري من قصّةِ سيدنا إسحاقَ عليه السلام أنْ نكرمَ الضيف، وأنْ نثقَ بأنَّ اللهَ قادرٌ على كلِّ شيء، وأنْ نشكرَه على هداياه. تصبحُ على خير."}],"question":{"q":"ماذا فعلَ إبراهيمُ عليه السلام عندما جاءَه الضيوف؟","options":["أكرمَهم وقدّمَ لهم الطعام","لم يفتحْ لهم الباب","طلبَ منهم الرحيل"],"answer":0},"activity":"عندما يزورُكم ضيف، ساعدْ أهلَك في تقديمِ الماءِ أو الضيافة، وقلْ له: أهلًا وسهلًا."},
{"id":"p10-yaqub","sort":240,"title":"سيدنا يعقوب عليه السلام والصبر الجميل","emoji":"🌤️","value_code":"sabr","value_name":"الصبر والأمل","kind":"prophet","minutes":3,"source":"القرآن الكريم: البقرة 132-133، يوسف 4-18، يوسف 83-100","min_grade":1,"max_grade":12,"pages":[{"bg":"garden","scene":["🏡","🌳","🐑"],"text":"يا صغيري، يعقوبُ عليه السلام نبيٌّ كريم، هو ابنُ سيدنا إسحاق، وحفيدُ سيدنا إبراهيم عليهم السلام. وكان له اثنا عشرَ ابنًا، منهم يوسفُ عليه السلام. وكان يعقوبُ أبًا حنونًا يعلّمُ أبناءَه حبَّ اللهِ وطاعتَه."},{"bg":"dusk","scene":["🌅","💧","🕯️"],"text":"وفي يومٍ رجعَ إخوةُ يوسفَ بدونه، وقالوا لأبيهم كلامًا لم يكنْ صحيحًا. فحزنَ يعقوبُ حزنًا شديدًا، لكنّه لم يغضبْ ولم ييأس، بل قال: «فصبر جميل والله المستعان على ما تصفون» (يوسف 18). والصبرُ الجميلُ يا صغيري هو الصبرُ الذي لا شكوى فيه للناس."},{"bg":"night","scene":["🌙","🤍","✨"],"text":"ومرّتْ سنواتٌ طويلة، ويعقوبُ يشتاقُ إلى ابنِه. ولم يكنْ يشكو حزنَه إلّا إلى ربِّه، فقال: «إنما أشكو بثي وحزني إلى الله» (يوسف 86). وكان قلبُه مليئًا بالأملِ في رحمةِ الله."},{"bg":"garden","scene":["🌤️","🌱","💬"],"text":"وقال لأبنائه كلمةً عظيمة: «يا بني اذهبوا فتحسسوا من يوسف وأخيه ولا تيأسوا من روح الله» (يوسف 87). يعني: ابحثوا عنه، ولا تفقدوا الأملَ أبدًا في رحمةِ الله، فاللهُ قادرٌ على أنْ يجمعَنا."},{"bg":"garden","scene":["👕","🌈","✨"],"text":"وصدقَ أملُه! فقد وجدَ الإخوةُ يوسفَ في مصر، وأرسلَ يوسفُ قميصَه مع البشير، قال تعالى: «فلما أن جاء البشير ألقاه على وجهه فارتد بصيرا» (يوسف 96). فعادَ بصرُ يعقوبَ عليه السلام، ثمَّ اجتمعتِ العائلةُ كلُّها من جديد."},{"bg":"night","scene":["🌙","🏡","💛"],"text":"وقبلَ أنْ يفارقَ يعقوبُ الدنيا، جمعَ أبناءَه وسألَهم: «ما تعبدون من بعدي» (البقرة 133)؟ فقالوا: «نعبد إلهك وإله آبائك إبراهيم وإسماعيل وإسحاق إلها واحدا» (البقرة 133). تعلّمْنا يا صغيري من سيدنا يعقوبَ الصبرَ الجميل، وألّا نيأسَ من رحمةِ الله. تصبحُ على خير."}],"question":{"q":"ماذا قال يعقوبُ عليه السلام لأبنائه عن رحمةِ الله؟","options":["لا تيأسوا من روحِ الله","اتركوا البحث","ناموا مبكّرًا"],"answer":0},"activity":"إذا حدثَ لك شيءٌ يُحزنُك، قلْ: «فصبر جميل» (يوسف 18)، ثمَّ ادعُ اللهَ أنْ ييسّرَ لك الخير."},
{"id":"p11-yusuf","sort":250,"title":"سيدنا يوسف عليه السلام والرؤيا","emoji":"🌾","value_code":"afw","value_name":"العفو والصبر","kind":"prophet","minutes":4,"source":"القرآن الكريم: سورة يوسف (4-21، 36-56، 88-100)","min_grade":1,"max_grade":12,"pages":[{"bg":"night","scene":["⭐","🌙","☀️"],"text":"يا صغيري، هذه قصّةٌ من أجملِ قصصِ القرآن، وقد قال اللهُ في أوّلِ سورتِها: «نحن نقص عليك أحسن القصص» (يوسف 3). إنّها قصّةُ يوسفَ عليه السلام. كان صغيرًا حين رأى في منامِه رؤيا عجيبة، فقال لأبيه يعقوب: «إني رأيت أحد عشر كوكبا والشمس والقمر رأيتهم لي ساجدين» (يوسف 4). فنصحَه أبوه ألّا يحكيَها لإخوتِه."},{"bg":"desert","scene":["🕳️","🐪","🌴"],"text":"وكان إخوتُه يغارون منه لأنَّ أباهم يحبُّه كثيرًا، فأخذوه وتركوه في بئر، قال تعالى: «وأجمعوا أن يجعلوه في غيابت الجب» (يوسف 15). لكنَّ اللهَ كان معه. فمرّتْ قافلةٌ من المسافرين، وأخرجوه من البئر، وأخذوه معهم إلى مصر."},{"bg":"city","scene":["🏛️","📚","✨"],"text":"وعاشَ يوسفُ في مصرَ في بيتِ رجلٍ كبير، وكبرَ هناك، وأعطاه اللهُ العلمَ والحكمة. ومرَّ بامتحاناتٍ صعبة، ودخلَ السجنَ وهو بريء، لكنّه بقيَ صابرًا، يعبدُ اللهَ ويدعو الناسَ إلى الخير، ويفسّرُ لهم أحلامَهم بما علّمَه الله."},{"bg":"garden","scene":["🐄","🌾","🏛️"],"text":"ورأى ملكُ مصرَ في المنامِ سبعَ بقراتٍ سمان وسبعَ سنبلاتٍ خضر، فلم يعرفْ أحدٌ تفسيرَها إلّا يوسف. ففسّرَها: ستأتي سبعُ سنواتٍ فيها خيرٌ كثير، ثمَّ سبعُ سنواتٍ قليلةُ المطر، فاحفظوا القمحَ في سنابلِه. فأعجبَ الملكَ علمُه، وقال يوسف: «اجعلني على خزائن الأرض إني حفيظ عليم» (يوسف 55)."},{"bg":"city","scene":["🌾","🐪","💛"],"text":"وفي سنواتِ القحط، جاءَ إخوتُه إلى مصرَ يطلبون الطعام، ولم يعرفوه. وبعدَ مدّةٍ عرّفَهم بنفسِه. وكان يستطيعُ أنْ يعاقبَهم، لكنّه عفا عنهم وقال: «لا تثريب عليكم اليوم يغفر الله لكم وهو أرحم الراحمين» (يوسف 92). يعني: لا لومَ عليكم اليوم."},{"bg":"night","scene":["⭐","☀️","🌙"],"text":"ثمَّ جاءَ أبواه وإخوتُه إلى مصر، واجتمعتِ العائلة، وتحقّقتِ الرؤيا التي رآها وهو صغير، فقال: «يا أبت هذا تأويل رؤياي من قبل قد جعلها ربي حقا» (يوسف 100). تعلّمْنا يا صغيري من سيدنا يوسفَ الصبرَ، والأمانة، والعفوَ عمّن أخطأ في حقِّنا. تصبحُ على خير."}],"question":{"q":"ماذا فعلَ يوسفُ عليه السلام مع إخوتِه في النهاية؟","options":["عاقبَهم","عفا عنهم وسامحَهم","لم يكلّمْهم"],"answer":1},"activity":"هل غضبتَ من أحدٍ اليوم؟ سامحْه قبلَ أنْ تنام، وقلْ في نفسِك: سامحتُك، مثلَ سيدنا يوسف."},
{"id":"p12-ayyub","sort":260,"title":"سيدنا أيوب عليه السلام والصبر","emoji":"💧","value_code":"sabr","value_name":"الصبر","kind":"prophet","minutes":3,"source":"القرآن الكريم: الأنبياء 83-84، ص 41-44","min_grade":1,"max_grade":12,"pages":[{"bg":"garden","scene":["🌳","🏡","🌸"],"text":"يا صغيري، أيوبُ عليه السلام نبيٌّ من أنبياءِ الله، ضربَ اللهُ به المثلَ في الصبر. أخبرَنا القرآنُ أنّه أصابَه تعبٌ ومرضٌ وابتلاءٌ شديد، وطالَ عليه ذلك، لكنّه بقيَ صابرًا يذكرُ اللهَ ويشكرُه."},{"bg":"night","scene":["🌙","🤍","⭐"],"text":"ولم يغضبْ أيوبُ ولم يعترض، بل دعا ربَّه بأدبٍ جميل: «وأيوب إذ نادى ربه أني مسني الضر وأنت أرحم الراحمين» (الأنبياء 83). انظرْ يا صغيري كيف دعا: أخبرَ اللهَ بحالِه، ثمَّ ذكرَ رحمتَه، ولم يطلبْ بغضب."},{"bg":"garden","scene":["⛲","💧","🌿"],"text":"فاستجابَ اللهُ دعاءَه، وقال له: «اركض برجلك هذا مغتسل بارد وشراب» (ص 42). يعني اضربِ الأرضَ برجلِك، فخرجَ له ماءٌ باردٌ يغتسلُ منه ويشربُ، فشفاه اللهُ وذهبَ عنه التعب."},{"bg":"garden","scene":["🌈","🏡","🌻"],"text":"وأكرمَه اللهُ وأعادَ إليه أهلَه وزادَه خيرًا، قال تعالى: «فاستجبنا له فكشفنا ما به من ضر وآتيناه أهله ومثلهم معهم رحمة من عندنا وذكرى للعابدين» (الأنبياء 84). فبعدَ الصبرِ يأتي الفرجُ والخير."},{"bg":"night","scene":["🌙","✨","💧"],"text":"ومدحَه اللهُ فقال: «إنا وجدناه صابرا نعم العبد إنه أواب» (ص 44). والأوّابُ هو الذي يرجعُ إلى اللهِ دائمًا. تعلّمْنا يا صغيري من سيدنا أيوبَ أنْ نصبرَ إذا مرضنا أو تعبنا، وأنْ ندعوَ اللهَ بأدب. تصبحُ على خيرٍ وعافية."}],"question":{"q":"بماذا مدحَ اللهُ أيوبَ عليه السلام؟","options":["إنّه كان صابرًا","إنّه كان غنيًّا","إنّه كان مسافرًا"],"answer":0},"activity":"احفظْ دعاءَ سيدنا أيوب: «أني مسني الضر وأنت أرحم الراحمين» (الأنبياء 83)، وادعُ به لكلِّ مريضٍ تعرفُه."},
{"id":"p13-shuayb","sort":270,"title":"سيدنا شعيب عليه السلام والميزان","emoji":"⚖️","value_code":"amana","value_name":"الأمانة في البيع والشراء","kind":"prophet","minutes":3,"source":"القرآن الكريم: الأعراف 85-93، هود 84-95، الشعراء 176-189","min_grade":1,"max_grade":12,"pages":[{"bg":"city","scene":["🏪","🌾","🐑"],"text":"يا صغيري، أرسلَ اللهُ شعيبًا عليه السلام إلى قومٍ اسمُهم أهلُ مدين، قال تعالى: «وإلى مدين أخاهم شعيبا» (الأعراف 85). وكانوا تجّارًا يبيعون ويشترون في الأسواق، وأعطاهم اللهُ خيرًا كثيرًا."},{"bg":"city","scene":["⚖️","🪙","🏪"],"text":"لكنَّ كثيرًا منهم كانوا يغشّون في البيع، فإذا وزنوا للناسِ أنقصوا الميزان، وأخذوا حقَّهم كاملًا لأنفسِهم. وهذا ظلمٌ لا يحبُّه الله. فنصحَهم شعيبٌ عليه السلام: «فأوفوا الكيل والميزان ولا تبخسوا الناس أشياءهم» (الأعراف 85)."},{"bg":"forest","scene":["🌳","🌿","⚖️"],"text":"وكان يقولُ لهم أيضًا: «وزنوا بالقسطاس المستقيم» (الشعراء 182)، يعني زِنوا بالميزانِ العادلِ المستقيم. وكان صادقًا يريدُ لهم الخير، فقال: «إن أريد إلا الإصلاح ما استطعت وما توفيقي إلا بالله» (هود 88)."},{"bg":"dusk","scene":["⛰️","☁️","🌙"],"text":"لكنَّ أكثرَهم رفضوا النصيحة، وأصرّوا على الغشّ، فنزلَ بهم عقابُ الله. أمّا شعيبٌ والذين آمنوا معه فقد نجّاهم الله، قال تعالى: «ولما جاء أمرنا نجينا شعيبا والذين آمنوا معه برحمة منا» (هود 94)."},{"bg":"night","scene":["⚖️","✨","🌙"],"text":"تعلّمْنا يا صغيري من سيدنا شعيبٍ عليه السلام أنْ نكونَ أمناءَ صادقين، لا نغشُّ في البيعِ ولا في اللعب ولا في الامتحان، وأنْ نعطيَ كلَّ أحدٍ حقَّه كاملًا. فالأمانةُ تجلبُ البركةَ ومحبّةَ الناس. تصبحُ على خيرٍ يا صغيري الأمين."}],"question":{"q":"بماذا نصحَ شعيبٌ عليه السلام قومَه؟","options":["أنْ يوفوا الكيلَ والميزان ولا يغشّوا","أنْ يتركوا البيع","أنْ يسافروا بعيدًا"],"answer":0},"activity":"العبْ مع أهلِك لعبةَ السوقِ الأمين: بِعْ واشترِ بميزانٍ أو بعدٍّ صحيح، وتأكّدْ أنَّ كلَّ واحدٍ أخذَ حقَّه كاملًا."},
{"id":"p14-musa","sort":280,"title":"سيدنا موسى عليه السلام والبحر","emoji":"🌊","value_code":"tawakkul","value_name":"الثقة بالله والشجاعة","kind":"prophet","minutes":4,"source":"القرآن الكريم: القصص 7-28، طه 9-47، الشعراء 52-67","min_grade":1,"max_grade":12,"pages":[{"bg":"river","scene":["🧺","🌊","🌿"],"text":"يا صغيري، وُلدَ موسى عليه السلام في مصر، في زمنِ ملكٍ ظالمٍ اسمُه فرعون. فألهمَ اللهُ أمَّه: «أن أرضعيه فإذا خفت عليه فألقيه في اليم ولا تخافي ولا تحزني إنا رادوه إليك» (القصص 7). فوضعتْه في صندوقٍ صغير، وتركتْه يطفو على ماءِ النهرِ بحفظِ الله."},{"bg":"river","scene":["🏛️","🧺","💛"],"text":"ووصلَ الصندوقُ إلى قصرِ فرعون، فأحبّتْه امرأةُ فرعون وقالت: «قرت عين لي ولك» (القصص 9)، يعني: هذا الطفلُ فرحةٌ لي ولك. ولم يقبلْ موسى أنْ يرضعَ من أيِّ امرأة، حتى أعادَه اللهُ إلى أمِّه، قال تعالى: «فرددناه إلى أمه كي تقر عينها ولا تحزن» (القصص 13). وهكذا تحقّقَ وعدُ الله."},{"bg":"desert","scene":["💧","🐑","🌳"],"text":"ولمّا كبرَ موسى خرجَ إلى بلدٍ اسمُه مدين، فوجدَ عندَ البئرِ فتاتين تنتظران لتسقيا غنمَهما، فسقى لهما، ثمَّ ذهبَ إلى الظلِّ ودعا: «رب إني لما أنزلت إلي من خير فقير» (القصص 24). فرزقَه اللهُ بيتًا وعملًا وأهلًا."},{"bg":"mountain","scene":["⛰️","🔥","✨"],"text":"وفي طريقِ عودتِه رأى نارًا عندَ جبل، فلمّا اقتربَ منها ناداه الله: «إني أنا ربك فاخلع نعليك إنك بالواد المقدس طوى» (طه 12). وكلّمَه اللهُ واختارَه نبيًّا، وأمرَه أنْ يذهبَ إلى فرعونَ مع أخيه هارون، وأنْ يكلّماه بلطف: «فقولا له قولا لينا» (طه 44)."},{"bg":"sea","scene":["🌊","🌊","🛤️"],"text":"ودعا موسى فرعونَ إلى عبادةِ الله، فرفضَ وتكبّر. فخرجَ موسى ومَن آمنَ معه ليلًا، فلحقَ بهم فرعونُ وجنودُه حتى وصلوا إلى البحر. فقال أصحابُ موسى: سيدركوننا! فقال موسى بكلِّ ثقة: «كلا إن معي ربي سيهدين» (الشعراء 62)."},{"bg":"sea","scene":["🌊","✨","🌊"],"text":"فأوحى اللهُ إليه: «أن اضرب بعصاك البحر فانفلق» (الشعراء 63). فانشقَّ البحرُ وصارَ فيه طريقٌ يابس، فعبرَ موسى ومَن معه بسلام، قال تعالى: «وأنجينا موسى ومن معه أجمعين» (الشعراء 65). أمّا فرعونُ الظالمُ فلم ينجُ."},{"bg":"night","scene":["🌙","⛰️","✨"],"text":"تعلّمْنا يا صغيري من سيدنا موسى عليه السلام أنَّ اللهَ يحفظُ عبادَه حتى وهم صغار، وأنْ نساعدَ المحتاجَ دونَ أنْ ننتظرَ شيئًا، وأنْ نقولَ في الأوقاتِ الصعبة: إنَّ معي ربّي. تصبحُ على خيرٍ في حفظِ الله."}],"question":{"q":"ماذا قال موسى عليه السلام عندما وصلوا إلى البحر؟","options":["سنرجعُ إلى الوراء","كلا إنَّ معي ربّي سيهدين","لا أعرفُ ماذا أفعل"],"answer":1},"activity":"ساعدْ غدًا شخصًا يحتاجُ مساعدة (مثلَ أخيك أو جدّتِك) دونَ أنْ تطلبَ شيئًا، كما سقى موسى للفتاتين."},
{"id":"p15-harun","sort":290,"title":"سيدنا هارون عليه السلام أخو موسى","emoji":"💞","value_code":"taawun","value_name":"التعاون بين الإخوة","kind":"prophet","minutes":3,"source":"القرآن الكريم: طه 25-36 و90-94، القصص 34-35، مريم 53، الأعراف 142","min_grade":1,"max_grade":12,"pages":[{"bg":"mountain","scene":["⛰️","✨","💞"],"text":"يا صغيري، هارونُ عليه السلام هو أخو سيدنا موسى عليه السلام. وعندما اختارَ اللهُ موسى نبيًّا، طلبَ موسى من ربِّه أنْ يجعلَ أخاه معه يعينُه: «واجعل لي وزيرا من أهلي هارون أخي اشدد به أزري وأشركه في أمري» (طه 29-32)."},{"bg":"mountain","scene":["💬","🌟","📜"],"text":"وكان هارونُ فصيحًا يحسنُ الكلام، قال موسى: «وأخي هارون هو أفصح مني لسانا فأرسله معي ردءا يصدقني» (القصص 34). فاستجابَ اللهُ لموسى، قال تعالى: «ووهبنا له من رحمتنا أخاه هارون نبيا» (مريم 53). انظرْ يا صغيري كيف كان الأخُ هديّةً ورحمةً لأخيه."},{"bg":"city","scene":["🏛️","💬","🌿"],"text":"وذهبَ الأخوان معًا إلى فرعون، وأمرَهما اللهُ أنْ يكلّماه بلطف: «فقولا له قولا لينا لعله يتذكر أو يخشى» (طه 44). فكانا فريقًا واحدًا، يساعدُ كلٌّ منهما الآخر، ويدعوان الناسَ إلى الخير بالكلمةِ الطيّبة."},{"bg":"desert","scene":["⛺","🌙","💬"],"text":"ولمّا ذهبَ موسى إلى الجبلِ لميعادِ ربِّه، تركَ هارونَ مع قومِه وقال له: «اخلفني في قومي وأصلح» (الأعراف 142). وعندما أخطأ بعضُ الناس، نصحَهم هارونُ بلطف: «يا قوم إنما فتنتم به وإن ربكم الرحمن فاتبعوني وأطيعوا أمري» (طه 90)."},{"bg":"night","scene":["💞","🌙","✨"],"text":"ودعا موسى لنفسِه ولأخيه معًا: «رب اغفر لي ولأخي وأدخلنا في رحمتك» (الأعراف 151). تعلّمْنا يا صغيري من سيدنا هارونَ عليه السلام أنْ نساعدَ إخوتَنا، وأنْ نتعاونَ معهم، وأنْ ندعوَ لهم. قلْ الآن: يا ربِّ احفظْ أخي. تصبحُ على خير."}],"question":{"q":"لماذا طلبَ موسى عليه السلام أنْ يكونَ هارونُ معه؟","options":["ليساعدَه ويعينَه","ليلعبَ معه","ليسافرَ بدلًا منه"],"answer":0},"activity":"اعملْ غدًا عملًا مع أخيك أو أختِك معًا (ترتيبُ الغرفة أو رسمُ لوحة)، وادعُ لهما: «رب اغفر لي ولأخي» (الأعراف 151)."},
{"id":"p16-dhulkifl","sort":300,"title":"سيدنا ذو الكفل عليه السلام","emoji":"🌿","value_code":"sabr","value_name":"الصبر وعمل الخير","kind":"prophet","minutes":3,"source":"القرآن الكريم: الأنبياء 85-86، ص 48","min_grade":1,"max_grade":12,"pages":[{"bg":"garden","scene":["🌿","🌸","✨"],"text":"يا صغيري، ذو الكفلِ عليه السلام ذكرَه اللهُ في القرآنِ الكريمِ مع الأنبياء، وأكثرُ العلماءِ على أنّه نبيٌّ من أنبياءِ الله. ولم يخبرْنا القرآنُ بتفاصيلِ قصّتِه، لكنّه أخبرَنا بصفاتِه الطيّبة، وهذا يكفينا لنحبَّه ونتعلّمَ منه."},{"bg":"garden","scene":["🌱","🌳","⏳"],"text":"قال اللهُ تعالى: «وإسماعيل وإدريس وذا الكفل كل من الصابرين» (الأنبياء 85). فكان ذو الكفلِ صابرًا: يصبرُ على طاعةِ الله، ويصبرُ على التعب، ويصبرُ حتى يتمَّ عملَه الطيّب."},{"bg":"dusk","scene":["💎","✨","🌙"],"text":"وقال تعالى عنه أيضًا: «وأدخلناهم في رحمتنا إنهم من الصالحين» (الأنبياء 86). وفي سورةٍ أخرى قال: «واذكر إسماعيل واليسع وذا الكفل وكل من الأخيار» (ص 48). والأخيارُ يا صغيري هم الذين يحبّون الخيرَ ويعملونه."},{"bg":"night","scene":["🌙","🌿","⭐"],"text":"هذا ما ثبتَ في القرآنِ عن سيدنا ذي الكفلِ عليه السلام: من الصابرين، ومن الصالحين، ومن الأخيار، وأدخلَه اللهُ في رحمتِه. فلنكنْ مثلَه يا صغيري: نصبرُ ونعملُ الخير. تصبحُ على خيرٍ في رحمةِ الله."}],"question":{"q":"ما الصفاتُ التي ذكرَها القرآنُ لذي الكفلِ عليه السلام؟","options":["الصبرُ والصلاحُ والخير","السرعةُ في الجري","حبُّ السفر"],"answer":0},"activity":"اعملْ غدًا عملَ خيرٍ واحدًا وأكملْه حتى النهاية دونَ أنْ تملّ، مثلَ إكمالِ واجبِك أو مساعدةِ أمِّك."},
{"id":"p17-dawud","sort":310,"title":"سيدنا داود عليه السلام والجبال تسبّح","emoji":"🛡️","value_code":"shukr","value_name":"العمل والشكر","kind":"prophet","minutes":3,"source":"القرآن الكريم: البقرة 249-251، سبأ 10-11 و13، ص 17-20، الأنبياء 79-80، النساء 163","min_grade":1,"max_grade":12,"pages":[{"bg":"desert","scene":["⛰️","🛡️","✨"],"text":"يا صغيري، داودُ عليه السلام كان شابًّا شجاعًا مؤمنًا، خرجَ مع جيشٍ صغيرٍ من المؤمنين ضدَّ ملكٍ ظالمٍ قويٍّ اسمُه جالوت. وكان المؤمنون واثقين بالله، يقولون: «كم من فئة قليلة غلبت فئة كثيرة بإذن الله» (البقرة 249). فنصرَهم الله."},{"bg":"city","scene":["👑","📜","✨"],"text":"ثمَّ أكرمَ اللهُ داودَ فجعلَه ملكًا ونبيًّا: «وآتاه الله الملك والحكمة وعلمه مما يشاء» (البقرة 251). وأنزلَ عليه كتابًا اسمُه الزبور، قال تعالى: «وآتينا داوود زبورا» (النساء 163). وكان يحكمُ بين الناسِ بالعدل."},{"bg":"mountain","scene":["⛰️","🐦","🎶"],"text":"وكان داودُ يكثرُ من ذكرِ الله بصوتٍ جميل، فأمرَ اللهُ الجبالَ والطيورَ أنْ تسبّحَ معه: «يا جبال أوبي معه والطير» (سبأ 10). تخيّلْ يا صغيري: الجبالُ والعصافيرُ كلُّها تذكرُ اللهَ معه! قال تعالى: «إنا سخرنا الجبال معه يسبحن بالعشي والإشراق» (ص 18)."},{"bg":"home","scene":["🔥","⚙️","🛡️"],"text":"ومن عجائبِ ما أعطاه الله: «وألنا له الحديد» (سبأ 10)، أي جعلَ الحديدَ ليّنًا في يدِه، فكان يصنعُ منه دروعًا تحمي الناس، قال تعالى: «أن اعمل سابغات وقدر في السرد» (سبأ 11). فكان ملكًا ومع ذلك يعملُ بيدِه ويتقنُ عملَه."},{"bg":"night","scene":["🌙","🎶","✨"],"text":"وقال اللهُ لآلِ داود: «اعملوا آل داوود شكرا» (سبأ 13)، يعني اشكروا اللهَ بأعمالِكم الطيّبة. تعلّمْنا يا صغيري من سيدنا داودَ عليه السلام الشجاعة، والعملَ وإتقانَه، وكثرةَ ذكرِ الله. قلْ معي: سبحانَ الله، الحمدُ لله. تصبحُ على خير."}],"question":{"q":"ماذا كانت الجبالُ والطيورُ تفعلُ مع داودَ عليه السلام؟","options":["تسبّحُ اللهَ معه","تنامُ طوالَ اليوم","تهربُ بعيدًا"],"answer":0},"activity":"اصنعْ غدًا شيئًا بيدِك وأتقنْه (رسمة، أو ترتيبُ مكتبتِك)، وقلْ وأنت تعمل: سبحانَ الله."},
{"id":"p18-sulayman","sort":320,"title":"سيدنا سليمان عليه السلام والنملة","emoji":"🐜","value_code":"shukr","value_name":"الشكر والرحمة بالمخلوقات","kind":"prophet","minutes":3,"source":"القرآن الكريم: النمل 15-44، سبأ 12، الأنبياء 81","min_grade":1,"max_grade":12,"pages":[{"bg":"city","scene":["👑","🐦","🌬️"],"text":"يا صغيري، سليمانُ عليه السلام هو ابنُ سيدنا داود، وكان نبيًّا وملكًا عظيمًا. أعطاه اللهُ أشياءَ عجيبة: فهمَ كلامَ الطيور، وسخّرَ له الريح. قال سليمان: «يا أيها الناس علمنا منطق الطير وأوتينا من كل شيء» (النمل 16)."},{"bg":"garden","scene":["🐜","🐜","🌾"],"text":"وفي يومٍ كان يسيرُ مع جنودِه، فوصلوا إلى وادٍ فيه نملٌ كثير. فقالتْ نملةٌ صغيرة: «يا أيها النمل ادخلوا مساكنكم لا يحطمنكم سليمان وجنوده وهم لا يشعرون» (النمل 18). يعني ادخلوا بيوتَكم حتى لا يدوسوكم دونَ أنْ يروكم."},{"bg":"garden","scene":["🐜","🌼","🌸"],"text":"فسمعَها سليمانُ وفهمَ كلامَها، قال تعالى: «فتبسم ضاحكا من قولها» (النمل 19)، ولم يغضب، بل شكرَ اللهَ على نعمتِه وقال: «رب أوزعني أن أشكر نعمتك التي أنعمت علي وعلى والدي» (النمل 19). انظرْ يا صغيري كيف رحمَ النملةَ الصغيرة وشكرَ ربَّه."},{"bg":"desert","scene":["🐦","☀️","🏰"],"text":"وكان من جنودِه طائرٌ اسمُه الهدهد. غابَ يومًا، ثمَّ رجعَ بخبرٍ مهمّ: «وجئتك من سبإ بنبإ يقين» (النمل 22). وجدَ ملكةً وقومَها يسجدون للشمسِ بدلَ الله. فأرسلَ إليها سليمانُ رسالةً تبدأ: «إنه من سليمان وإنه بسم الله الرحمن الرحيم» (النمل 30)."},{"bg":"city","scene":["🏰","💎","✨"],"text":"وجاءتِ الملكةُ إلى سليمان، فرأتْ ما أعطاه اللهُ من النعم، وعرفتْ أنَّ الحقَّ مع سليمان، فآمنتْ بالله وقالت: «وأسلمت مع سليمان لله رب العالمين» (النمل 44). وهكذا كانتْ دعوتُه بالحكمةِ والرسالةِ الطيّبة."},{"bg":"night","scene":["🌙","🐜","✨"],"text":"تعلّمْنا يا صغيري من سيدنا سليمانَ عليه السلام أنْ نرحمَ الحيواناتِ حتى النملةَ الصغيرة، وأنْ نشكرَ اللهَ كلّما أعطانا نعمة، وأنْ ندعوَ إلى الخيرِ بالحكمة. والآن انتبهْ للنملِ حين تمشي، وقلْ: الحمدُ لله. تصبحُ على خير."}],"question":{"q":"ماذا فعلَ سليمانُ عليه السلام عندما سمعَ كلامَ النملة؟","options":["غضبَ منها","تبسّمَ وشكرَ الله","لم يسمعْها"],"answer":1},"activity":"راقبْ مع أهلِك النملَ في الحديقة دونَ أنْ تؤذيَه، وانظرْ كيف يتعاونُ في حملِ الطعام."},
{"id":"p19-ilyas","sort":330,"title":"سيدنا إلياس عليه السلام","emoji":"🌄","value_code":"taqwa","value_name":"التقوى وعبادة الله وحده","kind":"prophet","minutes":3,"source":"القرآن الكريم: الصافات 123-132، الأنعام 85","min_grade":1,"max_grade":12,"pages":[{"bg":"mountain","scene":["🌄","⛰️","✨"],"text":"يا صغيري، إلياسُ عليه السلام نبيٌّ أرسلَه اللهُ إلى قومِه، قال تعالى: «وإن إلياس لمن المرسلين» (الصافات 123). وذكرَ القرآنُ قصّتَه باختصار، فلنتعرّفْ على ما أخبرَنا به."},{"bg":"city","scene":["🪨","💬","🏘️"],"text":"كان قومُه يعبدون صنمًا اسمُه بَعْل، ويتركون عبادةَ اللهِ الذي خلقَهم. فقال لهم إلياس: «ألا تتقون أتدعون بعلا وتذرون أحسن الخالقين الله ربكم ورب آبائكم الأولين» (الصافات 124-126). يعني: كيف تدعون صنمًا لا يخلقُ شيئًا، وتتركون اللهَ أحسنَ الخالقين؟"},{"bg":"dusk","scene":["☁️","⛰️","🌙"],"text":"لكنَّ أكثرَ قومِه كذّبوه، إلّا عبادَ اللهِ المخلصين الذين آمنوا معه، قال تعالى: «إلا عباد الله المخلصين» (الصافات 128). وبقيَ إلياسُ ثابتًا على الحقّ يدعو إلى الله."},{"bg":"night","scene":["🌙","✨","🌄"],"text":"وأكرمَه اللهُ فقال: «سلام على إل ياسين» (الصافات 130)، وقال: «إنه من عبادنا المؤمنين» (الصافات 132)، وذكرَه مع الصالحين: «وزكريا ويحيى وعيسى وإلياس كل من الصالحين» (الأنعام 85). تعلّمْنا يا صغيري من سيدنا إلياسَ أنْ نعبدَ اللهَ وحدَه ونتّقيَه. تصبحُ على خير."}],"question":{"q":"إلى ماذا دعا إلياسُ عليه السلام قومَه؟","options":["إلى عبادةِ اللهِ وحدَه وترك الصنم","إلى بناءِ القصور","إلى السفرِ في البحر"],"answer":0},"activity":"تأمّلْ مع أهلِك شيئًا جميلًا خلقَه الله (السماء، شجرة، زهرة)، وقولوا معًا: «أحسن الخالقين» (الصافات 125)."},
{"id":"p20-alyasa","sort":340,"title":"سيدنا اليسع عليه السلام","emoji":"🌟","value_code":"khayr","value_name":"حبّ الخير","kind":"prophet","minutes":3,"source":"القرآن الكريم: الأنعام 83-90، ص 48","min_grade":1,"max_grade":12,"pages":[{"bg":"night","scene":["🌟","⭐","🌙"],"text":"يا صغيري، اليَسَعُ عليه السلام نبيٌّ من أنبياءِ الله، ذكرَه اللهُ في القرآنِ الكريمِ في موضعين، ولم يذكرْ تفاصيلَ قصّتِه. لكنَّ ذكرَ اللهِ له مع الأنبياءِ الكرام شرفٌ عظيم، فتعالَ نتعرّفْ على ما قالَه القرآنُ عنه."},{"bg":"garden","scene":["🌍","🌟","✨"],"text":"قال اللهُ تعالى: «وإسماعيل واليسع ويونس ولوطا وكلا فضلنا على العالمين» (الأنعام 86). يعني أنَّ اللهَ اختارَه وفضّلَه، وجعلَه من الأنبياءِ الذين هدى بهم الناس."},{"bg":"dusk","scene":["💎","🌸","✨"],"text":"وقال تعالى: «واذكر إسماعيل واليسع وذا الكفل وكل من الأخيار» (ص 48). فاليسعُ من الأخيار، أي من أفضلِ الناسِ وأحبِّهم للخير. وقال اللهُ عن هؤلاء الأنبياء: «أولئك الذين هدى الله فبهداهم اقتده» (الأنعام 90)، يعني اتّبعوا طريقَهم في الخير."},{"bg":"night","scene":["🌙","🌟","💛"],"text":"هذا ما أخبرَنا به القرآنُ عن سيدنا اليسعَ عليه السلام: فضّلَه الله، وجعلَه من الأخيار، وأمرَنا أنْ نقتديَ بهدى الأنبياء. فلنكنْ يا صغيري من محبّي الخير. تصبحُ على خيرٍ في رعايةِ الله."}],"question":{"q":"ماذا قال القرآنُ عن اليسعِ عليه السلام؟","options":["إنّه من الأخيار","إنّه كان تاجرًا","إنّه كان بحّارًا"],"answer":0},"activity":"اكتبْ أو ارسمْ مع أهلِك ثلاثةَ أعمالِ خيرٍ تريدُ أنْ تفعلَها هذا الأسبوع."},
{"id":"p21-yunus","sort":350,"title":"سيدنا يونس عليه السلام والحوت","emoji":"🐋","value_code":"dua","value_name":"الدعاء والتسبيح","kind":"prophet","minutes":3,"source":"القرآن الكريم: الصافات 139-148، الأنبياء 87-88، يونس 98، القلم 48-50","min_grade":1,"max_grade":12,"pages":[{"bg":"city","scene":["🏘️","💬","🌇"],"text":"يا صغيري، يونسُ عليه السلام نبيٌّ أرسلَه اللهُ إلى قومٍ كثيرين يدعوهم إلى عبادةِ الله، قال تعالى: «وإن يونس لمن المرسلين» (الصافات 139). ويسمّيه القرآنُ أيضًا ذا النون، والنونُ هو الحوت."},{"bg":"sea","scene":["🚢","🌊","☁️"],"text":"ولمّا لم يستجبْ قومُه، تركَهم وهو غاضبٌ منهم، قبلَ أنْ يأذنَ اللهُ له: «وذا النون إذ ذهب مغاضبا» (الأنبياء 87). فركبَ سفينةً مليئةً بالناس، ثمَّ وقعَ في البحر، فالتقمَه حوتٌ كبير بأمرِ الله، وحفظَه اللهُ في بطنِ الحوت."},{"bg":"night","scene":["🐋","🌊","✨"],"text":"وكان يونسُ في ظلماتٍ: ظلمةِ الليل، وظلمةِ البحر، وظلمةِ بطنِ الحوت. فتذكّرَ ربَّه ودعاه: «لا إله إلا أنت سبحانك إني كنت من الظالمين» (الأنبياء 87). اعترفَ بخطئه، وسبّحَ الله، وطلبَ رحمتَه."},{"bg":"sea","scene":["🏝️","🌿","☀️"],"text":"فاستجابَ اللهُ دعاءَه: «فاستجبنا له ونجيناه من الغم وكذلك ننجي المؤمنين» (الأنبياء 88). فخرجَ من بطنِ الحوتِ إلى الشاطئ متعبًا، فأنبتَ اللهُ فوقَه شجرةً تظلّلُه: «وأنبتنا عليه شجرة من يقطين» (الصافات 146)، فارتاحَ تحتَ ظلِّها حتى قويَ."},{"bg":"city","scene":["🏘️","💛","✨"],"text":"ثمَّ رجعَ يونسُ إلى قومِه، فوجدَهم قد آمنوا! قال تعالى: «وأرسلناه إلى مائة ألف أو يزيدون فآمنوا فمتعناهم إلى حين» (الصافات 147-148). فرحَ يونسُ كثيرًا، وعاشَ قومُه في خيرٍ ونعمة."},{"bg":"night","scene":["🌙","🐋","⭐"],"text":"تعلّمْنا يا صغيري من سيدنا يونسَ عليه السلام أنَّ اللهَ يسمعُنا في أيِّ مكان، حتى في أعماقِ البحر، وأنَّ الدعاءَ والتسبيحَ يفرّجان الهمّ. احفظْ دعاءَه وقلْه إذا ضاقَ صدرُك: لا إلهَ إلّا أنتَ سبحانَك. تصبحُ على خير."}],"question":{"q":"بماذا دعا يونسُ عليه السلام وهو في بطنِ الحوت؟","options":["لا إله إلا أنت سبحانك إني كنت من الظالمين","أريدُ سفينةً جديدة","لم يدعُ بشيء"],"answer":0},"activity":"احفظْ مع أهلِك دعاءَ سيدنا يونس: «لا إله إلا أنت سبحانك إني كنت من الظالمين» (الأنبياء 87)، وقولوه معًا ثلاثَ مرّات."},
{"id":"p22-zakariya","sort":360,"title":"سيدنا زكريا عليه السلام والدعاء الخفي","emoji":"🕯️","value_code":"dua","value_name":"الدعاء وعدم اليأس","kind":"prophet","minutes":3,"source":"القرآن الكريم: آل عمران 37-41، مريم 2-11، الأنبياء 89-90","min_grade":1,"max_grade":12,"pages":[{"bg":"home","scene":["🕯️","🍇","✨"],"text":"يا صغيري، زكريّا عليه السلام نبيٌّ كريم، كان يرعى مريمَ عليها السلام ويعتني بها. وكان كلّما دخلَ عليها في مكانِ عبادتِها وجدَ عندَها طعامًا، قال تعالى: «كلما دخل عليها زكريا المحراب وجد عندها رزقا قال يا مريم أنى لك هذا قالت هو من عند الله» (آل عمران 37)."},{"bg":"night","scene":["🌙","🤍","⭐"],"text":"وكان زكريّا قد كبرَ في السنّ، ولم يكنْ له ولد. فلمّا رأى رزقَ اللهِ لمريم، دعا ربَّه بصوتٍ هادئٍ لا يسمعُه أحد: «إذ نادى ربه نداء خفيا» (مريم 3). وقال في دعائه: «ولم أكن بدعائك رب شقيا» (مريم 4)، يعني: يا ربّ، ما دعوتُك مرّةً إلّا أكرمتَني."},{"bg":"home","scene":["🕯️","🎁","💫"],"text":"فاستجابَ اللهُ دعاءَه، وبشّرَه بولدٍ اسمُه يحيى: «يا زكريا إنا نبشرك بغلام اسمه يحيى لم نجعل له من قبل سميا» (مريم 7). يعني لم يُسمَّ أحدٌ قبلَه بهذا الاسم. ففرحَ زكريّا فرحًا كبيرًا، وتعجّبَ من قدرةِ الله."},{"bg":"dusk","scene":["🌅","📿","🌙"],"text":"وجعلَ اللهُ له علامة: «آيتك ألا تكلم الناس ثلاث ليال سويا» (مريم 10). فخرجَ إلى قومِه، وأشارَ إليهم أنْ يسبّحوا اللهَ صباحًا ومساءً: «فأوحى إليهم أن سبحوا بكرة وعشيا» (مريم 11)."},{"bg":"night","scene":["🌙","🕯️","✨"],"text":"ومدحَ اللهُ زكريّا وأهلَه فقال: «إنهم كانوا يسارعون في الخيرات ويدعوننا رغبا ورهبا وكانوا لنا خاشعين» (الأنبياء 90). تعلّمْنا يا صغيري من سيدنا زكريّا ألّا نيأسَ أبدًا من الدعاء، وأنَّ اللهَ يسمعُ حتى الدعاءَ الهادئَ في القلب. ادعُ الآن بما تحبّ، ثمَّ نمْ مطمئنًّا. تصبحُ على خير."}],"question":{"q":"كيف دعا زكريّا عليه السلام ربَّه؟","options":["بصوتٍ هادئٍ خفيّ","بالصراخ","لم يدعُ أبدًا"],"answer":0},"activity":"قبلَ النوم، ادعُ اللهَ دعاءً هادئًا في قلبِك بشيءٍ تحبُّه، وثقْ أنَّ اللهَ يسمعُك."},
{"id":"p23-yahya","sort":370,"title":"سيدنا يحيى عليه السلام والحكمة","emoji":"📗","value_code":"birr","value_name":"بر الوالدين","kind":"prophet","minutes":3,"source":"القرآن الكريم: مريم 7 و12-15، آل عمران 38-39، الأنبياء 90","min_grade":1,"max_grade":12,"pages":[{"bg":"home","scene":["🎁","🕯️","✨"],"text":"يا صغيري، يحيى عليه السلام هو الابنُ الذي رزقَه اللهُ لسيدنا زكريّا بعدَ دعاءٍ طويل. واسمُه اختارَه اللهُ له، ولم يُسمَّ به أحدٌ قبلَه، قال تعالى: «اسمه يحيى لم نجعل له من قبل سميا» (مريم 7)."},{"bg":"garden","scene":["📗","🌱","☀️"],"text":"وأعطاه اللهُ العلمَ والحكمةَ وهو صغير، وأمرَه بأخذِ كتابِ اللهِ بجدّ: «يا يحيى خذ الكتاب بقوة وآتيناه الحكم صبيا» (مريم 12). يعني يا صغيري: تعلّمْ واحفظْ واعملْ بما في الكتابِ بهمّةٍ ونشاط."},{"bg":"garden","scene":["💗","🌸","🏡"],"text":"وكان يحيى رحيمًا طاهرَ القلب، قال تعالى: «وحنانا من لدنا وزكاة وكان تقيا» (مريم 13). والأجملُ من ذلك أنّه كان بارًّا بوالديه: «وبرا بوالديه ولم يكن جبارا عصيا» (مريم 14). يعني يحسنُ إليهما ويطيعُهما، ولا يتكبّرُ ولا يعصي."},{"bg":"night","scene":["🌙","📗","✨"],"text":"وسلّمَ اللهُ عليه في كلِّ أحوالِه: «وسلام عليه يوم ولد ويوم يموت ويوم يبعث حيا» (مريم 15). تعلّمْنا يا صغيري من سيدنا يحيى عليه السلام حبَّ العلمِ منذُ الصغر، والرحمة، وبرَّ الوالدين. قبّلْ يدَ أمِّك وأبيك، ونمْ هادئًا. تصبحُ على خير."}],"question":{"q":"كيف كان يحيى عليه السلام مع والديه؟","options":["بارًّا بهما يحسنُ إليهما","لا يسمعُ كلامَهما","بعيدًا عنهما"],"answer":0},"activity":"افعلْ غدًا شيئًا يُفرحُ والديك دونَ أنْ يطلباه منك، مثلَ ترتيبِ حذائك أو إحضارِ الماءِ لهما."},
{"id":"p24-isa","sort":380,"title":"سيدنا عيسى عليه السلام ابن مريم","emoji":"🌴","value_code":"birr","value_name":"العبودية لله وبر الوالدة","kind":"prophet","minutes":3,"source":"القرآن الكريم: آل عمران 42-59، مريم 16-36، المائدة 46 و110، النساء 157-158، الصف 6","min_grade":1,"max_grade":12,"pages":[{"bg":"home","scene":["✨","🌟","🕯️"],"text":"يا صغيري، مريمُ عليها السلام امرأةٌ صالحة اختارَها اللهُ وطهّرَها. وجاءَتْها الملائكةُ ببشارة: «إن الله يبشرك بكلمة منه اسمه المسيح عيسى ابن مريم» (آل عمران 45). وخلقَ اللهُ عيسى من غيرِ أب، بقدرتِه، كما خلقَ آدمَ من غيرِ أبٍ ولا أمّ: «إن مثل عيسى عند الله كمثل آدم» (آل عمران 59)."},{"bg":"desert","scene":["🌴","💧","✨"],"text":"ولمّا وُلدَ عيسى، كانتْ أمُّه عندَ جذعِ نخلة، فأكرمَها الله: «وهزي إليك بجذع النخلة تساقط عليك رطبا جنيا» (مريم 25). فسقطَ عليها رطبٌ طازج، وجرى تحتَها ماء، وقيلَ لها: «فكلي واشربي وقري عينا» (مريم 26)."},{"bg":"home","scene":["🌟","💬","📜"],"text":"ثمَّ حدثتْ معجزةٌ عجيبة: تكلّمَ عيسى وهو طفلٌ صغيرٌ في المهد، فقال: «إني عبد الله آتاني الكتاب وجعلني نبيا» (مريم 30). وقال: «وبرا بوالدتي ولم يجعلني جبارا شقيا» (مريم 32). فأوّلُ ما قاله: أنا عبدُ الله، وأنا بارٌّ بأمّي."},{"bg":"garden","scene":["🐦","🟤","✨"],"text":"ولمّا كبرَ، أعطاه اللهُ معجزاتٍ كثيرة، كلُّها بإذنِ الله، قال: «أني أخلق لكم من الطين كهيئة الطير فأنفخ فيه فيكون طيرا بإذن الله» (آل عمران 49). وكان يشفي المرضى بإذنِ الله، وأنزلَ اللهُ عليه كتابًا اسمُه الإنجيل."},{"bg":"night","scene":["☁️","✨","🌙"],"text":"وأرادَ بعضُ الناسِ أنْ يؤذوه، فحفظَه اللهُ ولم يصلوا إليه: «بل رفعه الله إليه» (النساء 158). وبشّرَ عيسى بنبيٍّ يأتي بعدَه: «ومبشرا برسول يأتي من بعدي اسمه أحمد» (الصف 6)، وهو نبيُّنا محمّدٌ صلّى اللهُ عليه وسلّم."},{"bg":"night","scene":["🌴","🌙","⭐"],"text":"تعلّمْنا يا صغيري من سيدنا عيسى عليه السلام أنَّه عبدُ اللهِ ورسولُه، وأنَّ المعجزاتِ كلَّها بإذنِ الله، وأنَّ برَّ الأمِّ من أجملِ الأخلاق. اذهبْ الآن وقلْ لأمِّك: أحبّكِ يا أمّي. تصبحُ على خيرٍ في حفظِ الله."}],"question":{"q":"ماذا قال عيسى عليه السلام وهو طفلٌ في المهد؟","options":["إنّي عبدُ الله آتاني الكتاب","أريدُ أنْ ألعب","لم يقلْ شيئًا"],"answer":0},"activity":"ساعدْ أمَّك غدًا في عملٍ تحبُّه، وقلْ لها كلمةً جميلة، فعيسى عليه السلام كان بارًّا بوالدتِه."},
{"id":"p25-muhammad","sort":390,"title":"سيدنا محمد ﷺ خاتم النبيين","emoji":"🕌","value_code":"rahma","value_name":"الرحمة وحسن الخلق","kind":"prophet","minutes":3,"source":"القرآن الكريم: الضحى 6-8، العلق 1-5، القلم 4، الأنبياء 107، التوبة 40، الأحزاب 21 و40 و56، النصر 1-3؛ وبدء الوحي في غار حراء: صحيح البخاري (3)، والهجرة وبناء المسجد: صحيح البخاري (3906)، والمؤاخاة: صحيح البخاري (3780)","min_grade":1,"max_grade":12,"pages":[{"bg":"desert","scene":["🕋","🌴","🐪"],"text":"يا صغيري، هذه قصّةُ آخرِ الأنبياءِ وأحبِّهم إلينا، نبيِّنا محمّدٍ صلّى اللهُ عليه وسلّم. وُلدَ في مكّة، ونشأَ يتيمًا، فرعاه اللهُ وحفظَه، قال تعالى: «ألم يجدك يتيما فآوى» (الضحى 6). وكان منذُ صغرِه صادقًا أمينًا، يحبُّه الناس."},{"bg":"mountain","scene":["⛰️","🌙","📖"],"text":"وكان يحبُّ أنْ يتعبّدَ في غارٍ في جبلٍ اسمُه حِراء، كما في صحيحِ البخاري. وهناك نزلَ عليه أوّلُ ما نزلَ من القرآن: «اقرأ باسم ربك الذي خلق» (العلق 1). فصارَ رسولَ اللهِ إلى الناسِ جميعًا، يدعوهم إلى عبادةِ اللهِ وحدَه وإلى الأخلاقِ الطيّبة."},{"bg":"garden","scene":["💛","🌸","🕊️"],"text":"وكان أحسنَ الناسِ خُلقًا، قال تعالى: «وإنك لعلى خلق عظيم» (القلم 4). وكان رحيمًا بالكبيرِ والصغيرِ والحيوان، وأرسلَه اللهُ رحمةً للناسِ كلِّهم: «وما أرسلناك إلا رحمة للعالمين» (الأنبياء 107)."},{"bg":"desert","scene":["⛰️","🌙","🐪"],"text":"ولمّا آذاه بعضُ أهلِ مكّة، هاجرَ إلى المدينةِ مع صاحبِه أبي بكرٍ رضي الله عنه، واختبآ في غارٍ في الطريق. فلمّا قلقَ صاحبُه، طمأنَه النبيُّ صلّى اللهُ عليه وسلّم، قال تعالى: «إذ يقول لصاحبه لا تحزن إن الله معنا» (التوبة 40)."},{"bg":"city","scene":["🕌","🌴","✨"],"text":"وفي المدينةِ بنى المسجد، وآخى بينَ الناس، وانتشرَ الإسلامُ بفضلِ الله، حتى جاءَ نصرُ اللهِ ودخلَ الناسُ في دينِ اللهِ أفواجًا: «إذا جاء نصر الله والفتح ورأيت الناس يدخلون في دين الله أفواجا» (النصر 1-2). وهو خاتمُ الأنبياء، لا نبيَّ بعدَه: «ولكن رسول الله وخاتم النبيين» (الأحزاب 40)."},{"bg":"night","scene":["🌙","🕌","⭐"],"text":"وجعلَه اللهُ قدوتَنا: «لقد كان لكم في رسول الله أسوة حسنة» (الأحزاب 21). فلنتعلّمْ منه يا صغيري الصدقَ والرحمةَ وحسنَ الخلق. وأمرَنا اللهُ أنْ نصلّيَ عليه: «يا أيها الذين آمنوا صلوا عليه وسلموا تسليما» (الأحزاب 56). قلْ معي: اللهمَّ صلِّ وسلّمْ على نبيِّنا محمّد. تصبحُ على خير."}],"question":{"q":"لماذا أرسلَ اللهُ نبيَّنا محمّدًا صلّى اللهُ عليه وسلّم؟","options":["رحمةً للعالمين","ليبنيَ القصور","ليجمعَ المال"],"answer":0},"activity":"صلِّ على النبيِّ صلّى اللهُ عليه وسلّم عشرَ مرّاتٍ مع أهلِك، واختر خُلقًا من أخلاقِه (الصدق أو الرحمة) لتعملَ به غدًا."}]$json$;
begin
  update public.bedtime_stories set published = false;
  for st in select * from jsonb_array_elements(data) loop
    insert into public.bedtime_stories (id, sort, title, emoji, value_code, value_name, kind, minutes, source,
                                        min_grade, max_grade, pages, question, activity, published)
    values (st->>'id', (st->>'sort')::int, st->>'title', st->>'emoji', st->>'value_code', st->>'value_name',
            st->>'kind', (st->>'minutes')::int, st->>'source', (st->>'min_grade')::int, (st->>'max_grade')::int,
            st->'pages', st->'question', st->>'activity', true)
    on conflict (id) do update set sort = excluded.sort, title = excluded.title, emoji = excluded.emoji,
       value_code = excluded.value_code, value_name = excluded.value_name, kind = excluded.kind,
       minutes = excluded.minutes, source = excluded.source, min_grade = excluded.min_grade,
       max_grade = excluded.max_grade, pages = excluded.pages, question = excluded.question,
       activity = excluded.activity, published = true;
  end loop;
end $$;
